window.APP_ESSAY_PAPERS = window.APP_ESSAY_PAPERS || {};
window.APP_ESSAY_PAPERS["local1-資料庫應用"] = [{"roc":114,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=114190&c=345&s=2103&q=1","qs":[{"n":1,"q":"假設我們在資料庫系統中以下述指令定義 BOOK 表格：create table Book ( ID           char(5), Title        varchar(20) not null, Author        varchar(20), Price         numeric(8, 2), primary key (ID));接著依序執行下列指令： 指令 1：insert into BOOK values (‘11111’, ‘Sky’, ‘John’, 60000);  指令 2：insert into BOOK values (‘11211’, null, ‘John’, 80000);  指令 3：insert into BOOK values (‘11111’, ‘Ocean’, ‘John’, 10000);  指令 4：insert into BOOK values (‘11411’, ‘Ocean’, ‘Mary’, null);請依序判斷每個指令能否順利執行。若能順利執行，請說明該指令對資料庫的影響（如新增或刪除特定資料表的內容）；若不能順利執行，請詳細說明原因（如違反某種特定的限制）。最後並列出執行四個指令後BOOK 表格的內容。（25 分）","pt":25,"warn":["pua"]},{"n":2,"q":"若某研究機構需要建立一個資料庫系統，以管理該機構所有曾經執行過的計畫，經分析後得到下列需求： 每個計畫需要記錄其編號、名稱、預算金額、主持人、開始日期與結束日期。其中計畫編號不可重複以用來辨識不同的計畫，而日期則包含年份和月份。 每個委託單位則有編號、名稱、聯絡人姓名與電話等資訊，其中編號用以辨識不同單位。 一個計畫只能有一個委託單位，但一個單位可以贊助多個計畫案。請根據上述所有需求畫出一個實體關係圖（Entity-Relationship Diagram, ER Diagram），注意圖中必須標明實體集合、關係集合、屬性、主鍵和對應數量限制（Mapping Cardinality）等。此外，計畫的日期請使用複合屬性（Composite Attribute）的表示法。（20 分）","pt":20,"warn":["pua"]},{"n":3,"q":"在某圖書館所建立的關聯式資料庫系統中，定義了 BOOK 表格和BORROWER 兩個表格，前者記錄館中每本藏書的基本資料，包含國際標準書號（ISBN） 、書名（Title）、作者（Author）和價錢（Price）；後者表示借閱資料，包含借書者編號（No）    、書號（ISBN）和借閱日期（Date）。各表格屬性如下所示，其中除了屬性 Price 為數值型態，其餘屬性皆為字串型態，而主鍵則以底線標註：BOOK（ISBN, Title, Author, Price）BORROWER（No, ISBN, Date）請撰寫 SQL 查詢句，分別回答下列各子題： （每小題 10 分，共 30 分）\n（一）輸出價錢超過 200 元書籍的 ISBN。\n（二）找出編號「B01」之借書者，其所有借過書籍的書名。\n（三）找出每個借書者（以屬性 No 代表）所借閱的書籍總數。","pt":30,"warn":["fig"]},{"n":4,"q":"近年來大數據（Big Data）為資料庫系統帶來新的挑戰。首先詳述大數據最主要的 3 個特性（簡稱 3V）為何？其次說明在那種情境或應用下會產生大數據？最後建議使用那種軟體或技術來儲存大數據，並詳述你的理由。（25 分）","pt":25,"ref":"【破題】\n本題聚焦於巨量資料（Big Data）對傳統資料庫管理系統之衝擊。作答時應精準定義大數據經典核心特性 3V，接著連結高並行、多源異質的實際業務場景，最後針對海量與非結構化特性，評估並推薦適合的分散式或非關聯式儲存技術，展現從理論觀念到系統架構設計的整合分析能力。\n\n【答題架構】\n一、大數據的三大核心特性（3V）詳述\n（一）巨量性（Volume）：說明資料規模由傳統的十億位元組（GB）躍升至百萬兆位元組（TB、PB、EB）等級。海量歷史資料與每日激增紀錄遠超過單機儲存上限，傳統集中式資料庫難以負載。\n（二）速度性（Velocity）：強調資料產生、收集與處理的速度極快。包含即時資料流（Streaming Data）、微秒級感測回報，系統必須具備極高寫入吞吐量與低延遲的即時處理能力。\n（三）多樣性（Variety）：闡述資料格式突破單一結構化表格限制，涵蓋半結構化（如 JSON、XML、日誌檔）與非結構化資料（如社群文字、影音、感測封包），傳統關聯式綱要無法彈性適應。\n\n二、產生大數據的應用情境與案例說明\n（一）物聯網與智慧製造：大量工業機台、智慧電表或自駕車感測器，以毫秒級頻率持續產生巨量時序監控數據。\n（二）社群網路與電子商務平台：全球數億使用者同時進行點擊流追蹤、影音串流上傳、動態推文與商品互動，形成高並發且異質的資料洪流。\n（三）金融科技與即時風險監控：高頻交易紀錄、跨行轉帳金流以及全網即時防洗錢與詐欺偵測，兼具高速產生與海量分析需求。\n\n三、建議儲存軟體技術與選擇理由\n（一）技術選型建議：建議採用分散式檔案系統 Hadoop HDFS 搭配分散式寬欄資料庫 Apache Cassandra，或分散式文件資料庫 MongoDB。\n（二）技術選型理由：\n1. 水平擴充性（Scale-Out）：具備無共用架構（Shared-Nothing），能透過低成本商業硬體節點隨需橫向擴充，突破單機容量瓶頸。\n2. 高可用性與容錯機制：具備多副本儲存與分散式叢集協調機制，任一節點故障皆不影響系統運作與資料完整。\n3. 彈性綱目（Schema-Free）：天然支援半結構化資料，無須事先鎖定或頻繁變更資料庫表格綱要，能高效應對多樣性資料。\n\n【關鍵字】\n巨量資料、3V特性、巨量性、速度性、多樣性、半結構化資料、非結構化資料、物聯網、點擊流、Hadoop HDFS、Cassandra、MongoDB、水平擴展、無共用架構、高可用性、彈性綱目\n\n【作答提醒】\n作答時切記將 3V 的定義與後續的情境、儲存技術緊密扣合，避免各小題獨立零散作答。例如說明 Variety 時，應在技術推薦中呼應 NoSQL 的動態綱目優勢；說明 Velocity 與 Volume 時，應連結分散式橫向擴充與高寫入吞吐量。若時間充裕，可補充說明大數據後續延伸的第四 V（真實性 Veracity）或第五 V（價值 Value），展現延伸知識廣度。"}]},{"roc":113,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=113200&c=345&s=2103&q=1","qs":[{"n":1,"q":"假設在學校的教務系統中，需要記錄學生的基本資料，譬如：學號（ID）        、姓名（Name） 、就讀系別（Major）、連絡電話（Tel）、通訊地址（Address）等。請利用 SQL 標準語法定義此表格的綱要（Schema）  ，包含此表格的名稱「Student」，以及 5 個屬性對應到上述需要記錄的 5 類資料，及其合適的資料型態。注意，也必須替此表格定義適合的主鍵（Primary Key）   ，並說明如此定義的理由。（20 分）","pt":20,"ref":"【破題】\n本題測驗關聯式資料庫綱要定義語言（DDL）的實作能力，以及實體完整性中主鍵選擇的核心觀念。作答時須依 SQL 標準規範精準撰寫建立表格語法，給予各屬性最適資料型態與限制條件，並從唯一性、最小性與不可為空等面向嚴謹論證主鍵選擇依據。\n\n【答題架構】\n一、SQL 標準語法定義 Student 表格綱要\n依題目要求定義表格名稱 Student 及五項屬性，並指定合適型態與完整性限制：\nCREATE TABLE Student (\n    ID VARCHAR(10) NOT NULL,\n    Name VARCHAR(50) NOT NULL,\n    Major VARCHAR(50) NOT NULL,\n    Tel VARCHAR(20),\n    Address VARCHAR(200),\n    PRIMARY KEY (ID)\n);\n各欄位資料型態設計說明：\n（一）學號（ID）：考量各校編碼可能含英文字母或固定編碼，採用長度十碼之變長字元 VARCHAR(10) 或固定長度 CHAR(10)，並設定不可為空。\n（二）姓名（Name）與就讀系別（Major）：考量中英文姓名與系所名稱長度，使用變長字元 VARCHAR(50)，皆設定不可為空值。\n（三）連絡電話（Tel）與通訊地址（Address）：電話包含分機或國碼，宜以字串 VARCHAR(20) 儲存以避免前導零消失；地址長度較長，配置 VARCHAR(200)，允許初次建檔時為空。\n\n二、主鍵之選定與理由說明\n此表格唯一適合之主鍵為「學號（ID）」，理由如下：\n（一）唯一性（Uniqueness）：學校在每位學生註冊時皆會配發獨一無二之學號，在整個系統實體集合中能精準識別任一學生紀錄，絕不重複。\n（二）最小性（Minimality）：學號單一屬性即具備決定所有非鍵屬性的功能相依能力（ID 決定 Name、Major 等），無須引入多餘屬性構成複合鍵。\n（三）實體完整性與非空性（Entity Integrity & Not Null）：主鍵不可包含空值（NULL），學號由教務處統一核發且具備存在必然性。相較之下，學生姓名易有同名同姓衝突，電話與地址可能更換、共用或缺漏，皆不適合作為主鍵。\n（四）穩定性（Stability）：學號在學生修業與畢業期間終身不變，不會因外在因素頻繁更新，維護關聯參照完整性成本最低。\n\n【關鍵字】\n資料定義語言、CREATE TABLE、主鍵、實體完整性限制、唯一性、最小性、非空值限制、資料型態、功能相依、變長字元\n\n【作答提醒】\n撰寫 DDL 語法時應注意大小寫規範與標點符號完整度，屬性定義切忌將電話（Tel）設為整數型態（INTEGER），因為電話號碼可能含有前導零、連字號或分機號碼，使用整數會導致資料截斷或失真。說明主鍵理由時，務必對比說明為何姓名、電話不可作為主鍵，強化論述說服力。"},{"n":2,"q":"假設某間大學建立一個關聯式資料庫系統，以表格「Professor」和「Teach」分別記錄老師的個人基本資料和授課資料，其屬性中除了薪水（salary）和學期（semester）為整數型態外，其餘皆為字串型態。學期的表示法中前三位數字為學年，而第四位數字以「1」和「2」分別對應到上下學期。譬如，「1131」代表 113 學年度的上學期。兩個表格各自的屬性如下所示，其中主鍵以底線標註：Professor（ID, name, department, salary）Teach（ID, course, semester）請利用 SQL 查詢指令，分別回答下列問題：                  （每小題 10 分，共 30 分）\n（一）找出資工系中薪水大於 10 萬元的教授名字。\n（二）找出所有資管系教授於 1131 學期所開設的課程。\n（三）輸出每一個系的教授平均薪水和最高薪水。","pt":30,"warn":["fig"]},{"n":3,"q":"假設要為一個音樂串流平臺網站設計資料庫，請根據下列需求利用實體關係模式（Entity-Relationship model）進行規劃，並畫出對應的實體關係圖（ER-diagram）： 每首歌曲都要記錄其編號、歌名、歌手、作曲人和作詞人。 每個會員都要記錄其會員編號、姓名、地址和電話。 要記錄每首歌曲何時被收聽，包含收聽的會員、收聽的日期時間等。 歌曲分為多個類別，如抒情、搖滾、古典等。請注意圖中必須標明實體集合、關係集合、屬性、主鍵和對應數量限制（Mapping Cardinality）等，也可使用擴充實體關係模式（Extended ER model, EER）的表示法。     （20 分）","pt":20,"warn":["pua"]},{"n":4,"q":"下面名為「Register」的表格列舉學生修課的表現，其第一列為表格的欄位名稱，而欄位的意義依序為學號（ID）     、姓名（Name）、課名（Title）  、學分數（Credit）、成績（Grade），並假設此表格的主鍵由「ID」和「Title」兩個屬性所共同組合而成。請說明 BCNF（Boyce-Codd Normal Form）正規化格式的定義，與此表格未符合 BCNF 的原因，以及將此表格經過正規化處理後的結果。    （30 分）ID      Name   Title   Credit   Grade 11301   張三     資料庫     3        A 11301   張三     作業系統    3        C 11302   李四     資料庫     3        B 11302   李四     作業系統    3        B","pt":30,"warn":["math"]}]},{"roc":112,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=112200&c=346&s=2701&q=1","qs":[{"n":1,"q":"某圖書館有下列已知的相關資訊。．每本“書”有一個 ISBN 號碼，這個號碼是唯一的。每本書也有書名，作者，出版社，等資料需要記載下來。．每個“讀者”都有身分證號碼，姓名，和手機號碼。有些讀者可能有二個或者更多個手機，其號碼都要記錄下來。若某讀者來到圖書館，從來沒有借書，那麼他的個人資料，圖書館就不會記錄下來。只有那些有借過書的，圖書館才會記錄他的個資。．圖書館有若干“館員”，每個館員有身分證號碼、姓名、隸屬組別。其中，隸屬組別，指的是館員的工作性質。例如，有的是採購組，有的是編目組，有的是服務組，等等。每位館員只會隸屬於一個組。館員中，只有服務組的館員，會參與在處理讀者借書的程序中。．所有的“借閱紀錄”都要存記下來，也就是某位讀者，借出了某一本書，經由某位館員處理的，這個資訊要記錄下來。同時也要把借出日期，和歸還日期，記錄下來。讀者每次可借閱多本書。．此外，圖書館會不定期檢查圖書的“書籍狀態”，每次檢查若發現有狀況的書籍，則會把相關資訊記錄下來。這部分的資訊包括檢查日期，和狀態說明（例如，遺失、破損等等）。根據上述的說明，請使用實體－關係模型（Entity-Relationship model）來為這些資料設計出正確的綱目（ER schema），繪出其綱目圖（schema diagram）。其中關係（relationship）的基數比（cardinality ratio）請使用1:N, M:N…, 等 方 式 來 表 示 ， 並 且 請 在 圖 中 標 示 出 參 與 限 制 條 件（participation constraint）。（25 分）","pt":25,"ref":"【破題】\n本題測驗實體關係模型（ER Model）之概念塑模能力，核心在於正確識別實體、屬性、關係型態，並特別處理多值屬性、弱實體、多元關係，以及精確標示基數比（1:N、M:N）與完全／部分參與限制。\n\n【答題架構】\n一、實體集合（Entity Sets）與屬性設計\n（一）書（Book）：強實體。屬性包含 ISBN（主鍵，實底線）、書名、作者、出版社。\n（二）讀者（Reader）：強實體。屬性包含身分證號碼（主鍵，實底線）、姓名、手機號碼。特別注意手機號碼為多值屬性，在 ER 圖中應以雙橢圓表示。\n（三）館員（Librarian）：強實體。屬性包含身分證號碼（主鍵，實底線）、姓名、隸屬組別。\n（四）書籍狀態記錄（Book_Status）：弱實體（雙矩形）。依附於書實體，具備部分鍵（Partial Key）檢查日期（虛底線）與狀態說明屬性；透過識別關係「檢查」（雙菱形）與書連結。\n\n二、關係集合（Relationship Sets）、基數比與參與限制\n（一）借閱（Borrow）關係：\n1. 關係型態：由讀者、書、館員三者共同構成三元關係（Ternary Relationship），或以弱實體借閱紀錄表達。其關聯屬性包含借出日期、歸還日期。\n2. 基數比：讀者與書之間為 M:N（讀者可借多本書，一本書歷程可被多位讀者借閱）；館員對借閱為 1:N（館員可處理多筆借閱）。\n3. 參與限制：\n- 讀者：全部參與（Total Participation，雙線）。題目指明只有借過書的讀者才會記錄個資，因此資料庫中所有讀者皆必須參與借閱關係。\n- 書：部分參與（Partial Participation，單線）。未被借出或館內典藏書籍不一定有借閱紀錄。\n- 館員：部分參與（單線）。僅「服務組」館員參與借閱處理，採購組與編目組不參與。\n（二）書籍狀態檢查（Inspect）關係：\n書與書籍狀態記錄為 1:N 識別關係。書為部分參與（無狀況之書籍不記錄），書籍狀態記錄為全部參與（雙線，存在相依）。\n\n三、ER 綱目圖繪製呈現要點\n繪製時以標準符號表達：強實體用單矩形、弱實體用雙矩形、關聯用單菱形、識別關聯用雙菱形、多值屬性用雙橢圓、主鍵劃實底線、部分鍵劃虛底線、全部參與以雙實線連接。\n\n【關鍵字】\n實體關係模型、ER圖、基數比、參與限制、全部參與、部分參與、多值屬性、弱實體、部分鍵、三元關係、識別關係\n\n【作答提醒】\n本題有三大關鍵得分細節常被忽略：第一，「只有借過書的讀者才記錄」隱含讀者實體對借閱關係為「全部參與（雙線）」；第二，手機號碼可有多個，必須標記為「多值屬性（雙橢圓）」；第三，書籍檢查狀態依附於書且主鍵依賴，應設計為弱實體或明示依附關係。若繪圖空間有限，可先用條列式清楚交代各實體屬性與關係基數，再附上結構清晰的圖示。"},{"n":2,"q":"有一機票購買資料庫，含有以下的關連（relations）旅客（護照號碼，姓名，電話，年齡）航班（航班編號，航空公司，出發時間，抵達時間，出發地，目的地）購票資訊（護照號碼，航班編號，座位，票價）請用關連式代數（Relational Algebra）回答以下查詢（queries）：（每小題 10 分，共 20 分）\n（一）所有從“臺北”出發，到達目的地是“洛杉磯”的直飛的航班（亦即中間沒有停留任何其他機場）     ，列出這些航班上的旅客護照號碼和姓名。\n（二）針對從“臺北”出發的每一個航班，列出航班編號，和此航班所有乘客的平均年齡。","pt":20,"ref":"【破題】\n本題評量關聯式代數（Relational Algebra）的演算表達能力。解題關鍵在於熟練運用選取、投影、自然合併或等值合併運算子，並在第二小題正確運用分組聚集運算子計算平均年齡，維持關聯代數運算語法之嚴謹性。\n\n【答題架構】\n一、小題（一）查詢：從臺北直飛洛杉磯航班之旅客護照號碼與姓名\n（一）解題邏輯與運算步驟拆解：\n1. 篩選航班：自航班關聯中，選取出發地為「臺北」且目的地為「洛杉磯」之航班元組。\n2. 串接購票資訊：將篩選後之航班與購票資訊關聯進行自然合併（藉由航班編號）。\n3. 串接旅客資訊：再與旅客關聯進行自然合併（藉由護照號碼），以取得姓名欄位。\n4. 投影結果：最後投影出旅客的護照號碼與姓名。\n（二）關聯代數正式表達式：\n步驟化表示：\nR1 ← σ 出發地='臺北' ∧ 目的地='洛杉磯' (航班)\nR2 ← R1 ⨝ 購票資訊\nR3 ← R2 ⨝ 旅客\nResult ← π 旅客.護照號碼, 姓名 (R3)\n單一複合表達式：\nπ 護照號碼, 姓名 ( (σ 出發地='臺北' ∧ 目的地='洛杉磯' (航班)) ⨝ 購票資訊 ⨝ 旅客 )\n\n二、小題（二）查詢：臺北出發航班之航班編號與乘客平均年齡\n（一）解題邏輯與聚集運算設計：\n1. 篩選出發地為臺北的航班，並與購票資訊、旅客關聯依序合併，取得每位乘客之年齡資訊。\n2. 運用分組聚集運算子（使用 G、F 或伽瑪 γ 符號），以航班編號作為分組屬性，對年齡屬性進行 AVG 平均計算。\n（二）關聯代數正式表達式：\n步驟化表示：\nR1 ← σ 出發地='臺北' (航班)\nR2 ← R1 ⨝ 購票資訊 ⨝ 旅客\nResult ← 航班編號 𝒢 AVG(年齡) (R2)\n亦可表示為：\n航班編號 ℱ AVG(年齡) ( (σ 出發地='臺北' (航班)) ⨝ 購票資訊 ⨝ 旅客 )\n\n【關鍵字】\n關聯式代數、選取運算、投影運算、自然合併、聚集運算、分組運算、條件結合\n\n【作答提醒】\n考卷作答關聯代數時，建議先以「中間暫存關聯（R1, R2...）」逐步推導，最後再附上單一完整表達式，如此條理分明且不易失分。在合併運算時，若欄位同名可直接使用自然合併符號 ⨝。聚集運算符號在教科書中有 𝒢、ℱ 或 γ 多種標記方式，作答時可於括弧中簡短備註代表分組與聚集函數，閱卷老師皆能認同。"},{"n":3,"q":"承上題的資料庫綱目（schema），請用 SQL 回答下列查詢：（每小題 10 分，共 20 分）\n（一）我們想要查出有那些旅客，他們從來沒有搭乘過“甲航空”的任何一個航班的，列出這些旅客的護照號碼和姓名。\n（二）我們想要找出有那些航班的乘客人數是低於 10 人的（i.e.,<10），請列出這些航班所屬的航空公司，和該航班的航班編號，以及搭乘該航班的人數（注意，是低於 10 人的）。","pt":20,"ref":"【破題】\n本題測驗關聯式資料庫 SQL 查詢能力。第一小題核心在於反向排除邏輯（集合差集或子查詢）；第二小題重點在於分組統計與過濾條件（GROUP BY 與 HAVING），並須特別洞察「乘客人數為零」時的 OUTER JOIN 邊界處理。\n\n【答題架構】\n一、小題（一）SQL 查詢：未曾搭乘「甲航空」之旅客護照號碼與姓名\n（一）解題思維：先找出曾搭乘甲航空之所有旅客護照號碼，再自全體旅客中排除。\n（二）標準 SQL 語法（採用 NOT IN 或 NOT EXISTS）：\n寫法一（NOT IN 子查詢）：\nSELECT 護照號碼, 姓名\nFROM 旅客\nWHERE 護照號碼 NOT IN (\n    SELECT T.護照號碼\n    FROM 購票資訊 T\n    JOIN 航班 F ON T.航班編號 = F.航班編號\n    WHERE F.航空公司 = '甲航空'\n);\n寫法二（NOT EXISTS 相關子查詢）：\nSELECT P.護照號碼, P.姓名\nFROM 旅客 P\nWHERE NOT EXISTS (\n    SELECT 1\n    FROM 購票資訊 T\n    JOIN 航班 F ON T.航班編號 = F.航班編號\n    WHERE T.護照號碼 = P.護照號碼 AND F.航空公司 = '甲航空'\n);\n\n二、小題（二）SQL 查詢：乘客人數低於 10 人的航班、航空公司與人數\n（一）解題思維與邊界防禦：\n一般查詢若僅使用 INNER JOIN，人數為 0 的航班將直接被漏掉。題目指明人數「低於 10 人」，實務與嚴謹作答上應使用 LEFT JOIN 包含搭乘人數為 0 人的航班，並以 COUNT(購票資訊.護照號碼) 計數。\n（二）標準 SQL 語法：\nSELECT F.航空公司, F.航班編號, COUNT(T.護照號碼) AS 搭乘人數\nFROM 航班 F\nLEFT JOIN 購票資訊 T ON F.航班編號 = T.航班編號\nGROUP BY F.航空公司, F.航班編號\nHAVING COUNT(T.護照號碼) < 10;\n（若僅考慮已有購票紀錄但人數小於十人，則為 INNER JOIN 並搭配 HAVING COUNT(*) < 10，作答時可補充說明此差異）。\n\n【關鍵字】\nSQL、子查詢、NOT IN、NOT EXISTS、LEFT JOIN、GROUP BY、HAVING、COUNT、邊界條件、集合運算\n\n【作答提醒】\n第一小題使用 NOT IN 時，若子查詢結果含有空值可能導致邏輯失效，作答時提及 NOT EXISTS 是更健全防範空值的寫法，能獲得高度評價。第二小題是典型的高分陷阱題，多數考生只寫一般 INNER JOIN，忽略了人數為 0 人的航班也是「低於 10 人」；務必主動採用 LEFT JOIN 並計算購票記錄欄位，點出 0 人航班的存在情境，此為拉開分數差距的關鍵關鍵。"},{"n":4,"q":"有 5 個交易（transactions）T1, T2, T3, T4, T5，在被執行時，形成以下的程 序 （ schedule ）， 假 設 該 資 料 庫 管 理 系 統 的 恢 復 機 制 （ recovery mechanism）使用的是延遲更新協定（deferred update protocol）。並且假設系統在查核點時（checkpoint），會使所有正在執行的交易工作暫停，將已經完成的交易（committed transaction）的結果，強迫儲存（force write）到二線儲存器（secondary storage）         。請說明這 5 個交易在系統當機後，重新恢復時，各需要對這 5 個交易作什麼處置，並說明理由。                   （25 分）[start-transaction, T1] [read_item, T1, A] [start-transaction, T3] [read_item, T3, C] [write_item, T1, A, 10] [start-transaction, T4] [read_item, T4, D] [commit, T1] [write_item, T3, C, 20] [checkpoint] [read_item, T3, E] [write_item, T4, D, 30] [start-transaction, T2] [write_item, T3, E, 40] [commit, T3] [read_item, T2, B] [start-transaction, T5] [write_item, T2, B, 50] [read_item, T5, G] [commit, T2] [read_item, T4, H] [write_item, T5, G, 60] ← system crash","pt":25,"ref":"【破題】\n本題考核資料庫管理系統在延遲更新協定（Deferred Update Protocol，即 NO-UNDO/REDO 演算法）下，結合檢查點（Checkpoint）機制的系統當機復原策略。作答關鍵在於精準掌握延遲更新「未確認前不寫入磁碟資料庫」的本質，以及檢查點強制寫入對已完成交易的保護作用。\n\n【答題架構】\n一、延遲更新協定與查核點機制之復原原則\n（一）延遲更新協定核心原理：交易執行過程中的所有寫入操作只記錄在系統日誌（Log）中，直到交易發出 Commit 成功後，更新資料才會實際寫入磁碟資料庫。因此，尚未 Commit 的交易絕不會污染磁碟上的資料，復原時「絕不需要復原（NO-UNDO）」。\n（二）查核點（Checkpoint）作用：本題假設 Checkpoint 暫停執行中工作，並將所有在 Checkpoint 之前已 Commit 的交易結果強制寫入二線儲存器（Force Write）。因此 Checkpoint 之前已完成的交易已確保持久化。\n\n二、各交易執行歷程分析與復原處置\n依時間軸逐一審視 T1 至 T5 的狀態：\n（一）T1 的處置與理由：\n1. 處置：不需任何處置（No Action，既不 REDO 也不 UNDO）。\n2. 理由：T1 在 Checkpoint 之前已完成 Commit，且題目明確設定 Checkpoint 會將已 Commit 交易強制寫入二線儲存器，故 T1 的變更已完整寫入磁碟，無須重做。\n（二）T2 的處置與理由：\n1. 處置：需要重做（REDO T2）。\n2. 理由：T2 在 Checkpoint 之後開始執行，並在當機前完成 Commit。由於其更新可能仍停留在主記憶體緩衝區尚未排入磁碟，必須依據日誌重新執行寫入以確保耐久性。\n（三）T3 的處置與理由：\n1. 處置：需要重做（REDO T3）。\n2. 理由：T3 雖在 Checkpoint 前啟動，但其 Commit 發生在 Checkpoint 之後。Checkpoint 當時 T3 尚未完成，不會被強制寫入磁碟；故當機重啟後，必須依據日誌將 T3 的寫入項目重新執行（REDO）。\n（四）T4 的處置與理由：\n1. 處置：不需復原，忽略或重新執行（No UNDO / Ignore / Restart）。\n2. 理由：T4 在當機時尚未 Commit（處於活躍中）。因延遲更新協定在 Commit 前不寫入磁碟資料庫，磁碟未受修改，故無須 UNDO，只需由日誌清除或重新提交。\n（五）T5 的處置與理由：\n1. 處置：不需復原，忽略或重新執行（No UNDO / Ignore / Restart）。\n2. 理由：T5 在 Checkpoint 後啟動，至當機時仍未 Commit，實體資料庫無任何污染，同樣無須執行 UNDO。\n\n【關鍵字】\n資料庫復原、延遲更新協定、NO-UNDO/REDO、查核點、強制寫入、重做、復原處理、交易日誌、耐久性\n\n【作答提醒】\n最常見的嚴重失分點是誤將延遲更新協定套用成即時更新協定（Immediate Update / UNDO/REDO），誤寫要對 T4、T5 執行 UNDO。延遲更新的核心定義就是「NO-UNDO」，務必在開頭明確強調。此外，務必詳細區分 T1 與 T3 在 Checkpoint 前後 Commit 的時間差異，扣合題目「已完成交易會 force write」的前提，證明 T1 免做 REDO 而 T3 必須 REDO。"},{"n":5,"q":"試說明下列名詞之意涵：（每小題 5 分，共 10 分）\n（一）第二正規化（Second Normal Form）的定義\n（二）何謂 NoSQL","pt":10,"ref":"【破題】\n本題測驗關聯式資料庫正規化理論與現代非關聯式 NoSQL 資料庫之核心觀念。第一小題須從函數相依角度精準界定第二正規化消除部分相依的數學嚴謹定義；第二小題須全面涵蓋 NoSQL 的誕生背景、核心架構特性及四大主流類型。\n\n【答題架構】\n一、第二正規化（Second Normal Form, 2NF）之定義\n（一）基本先決條件：關聯綱要必須先符合第一正規化（1NF），即關聯表格中每一個屬性之值域皆為單一且不可分割之原子值（Atomic Values），無重複群或多值屬性。\n（二）核心規則（消除部分功能相依）：關聯中的每一個非主鍵屬性（Non-prime Attribute），都必須完全功能相依（Fully Functionally Dependent）於候選鍵（Candidate Key），不得存在部分功能相依（Partial Functional Dependency）。\n（三）實務意涵與轉換：若表格的主鍵由單一屬性構成，則只要符合 1NF 就自然符合 2NF。只有在主鍵為複合鍵（Composite Key）時，才會發生非鍵屬性僅依賴複合主鍵中某一部分屬性的情況，此時必須將該部分相依的屬性分割獨立為新表格。\n\n二、NoSQL（Not Only SQL）之意涵與特性\n（一）名詞意涵與背景：NoSQL 代表「Not Only SQL」，是為了因應網際網路爆發、大數據時代海量資料、高並發讀寫以及多樣化非結構化資料，突破傳統關聯式資料庫垂直擴展（Scale-Up）極限與固定綱目（Schema）束縛而發展出的分散式非關聯式資料庫架構。\n（二）核心設計架構特性：\n1. 彈性綱目（Schema-less / Dynamic Schema）：不需預先嚴格定義欄位結構，支援半結構化與非結構化資料快速變更。\n2. 水平擴充性（Scale-Out）：透過無共用叢集架構，隨需增加低成本節點以橫向擴展儲存容量與運算吞吐量。\n3. 遵循 BASE 理論與 CAP 定理權衡：放寬傳統 ACID 剛性要求，改為追求基本可用（Basically Available）、軟狀態（Soft State）與最終一致性（Eventual Consistency），在分區容忍性（P）前提下彈性取捨一致性（C）與可用性（A）。\n（三）四大主流資料模型分類：\n1. 鍵值儲存（Key-Value，如 Redis）。\n2. 文件資料庫（Document，如 MongoDB）。\n3. 寬欄/欄位式資料庫（Wide-Column / Column-Family，如 Cassandra、HBase）。\n4. 圖形資料庫（Graph，如 Neo4j）。\n\n【關鍵字】\n第二正規化、第一正規化、原子值、部分功能相依、完全功能相依、複合主鍵、NoSQL、彈性綱目、水平擴充、CAP定理、BASE理論、最終一致性\n\n【作答提醒】\n說明 2NF 時，切勿只用白話文含糊帶過，務必寫出「完全功能相依」與「非主鍵屬性」等標準學術名詞，並強調複合主鍵才是 2NF 的防範重點。說明 NoSQL 時，除列舉定義外，務必對比 RDBMS（ACID vs BASE、Scale-up vs Scale-out），並簡要帶出四大類型與 CAP 定理，方能奪取滿分。"}]},{"roc":111,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111190&c=348&s=2501&q=1","qs":[{"n":1,"q":"假設有關博物館的部分實體關係圖（Entity-Relationship Diagram）如下，其中每一實體（矩形）或弱實體（雙矩形）鄰近某關係（菱形）間均有一對（min,max）的限制，代表該實體參與該關係之 min（至少）、max（至多）次數限制，*代表沒有限制。屬性劃實底線者（如 MID、LID、C_Number）為 Primary Key（主鍵）、劃虛底線者（如 BID）為 Partial Key。\n（一）請將此圖轉化為對應的關聯（Relation）式資料庫綱要，以「關聯（屬性 1,屬性 2,……）」方式寫出應有的所有關聯表格；同時，必須標示出每個關聯的主鍵。（15 分）\n（二）進一步，若對實體關係圖中「館藏物」應有的關聯表格，以 SQL 語法的 CREATE 命令去創建它，其中應有的參考完整性限制（Referential Integrity Constraints）語句應為何？（5 分）","pt":20},{"n":2,"q":"假設有個資料庫的 Employee 表格，其屬性包含：編號 SID、姓名 Name、性別 Sex、居住街道地址 Street、居住城市 City、薪水 Salary、所屬部門編號 Dnumber。其目前的資料存於電腦中如下表，假設：身為程式設計師，你還不知電腦中有多少筆，及其詳細內容，但知道其綱要、欄位型態，並見到編號 SID 為 3001、4001 兩筆資料例子。SID     Name      Sex      Street       City      Salary Dnumber 1001   Alisa       F     中山一路 30 號    Palmer        8000        50 2001   Beatrice    F     信義南路 7 號     Lecanto      12000        30 3001   Abraham     M     中山二路 60 號    Warrendale    7000        30 4001   Dana        F     北中山一路 96 號   Enumclaw      6000        40 4044   Ferdinand   M     忠孝北路 66 號    Alameda       9000        40 5055   Grace       F     忠孝北路 99 號    Lecanto      25000        30 6004   John        M     南中山一路 30 號   Waterloo     36000        40 6006   Philemen    M     中山路 67 號     Smithville   16000        60 6008   Vince       M     仁愛西路 80 號    Wautoma      15000        50\n（一）請寫出 SQL 查詢，來列出：不管住那個城市，居住街道有「中山」二字者之員工編號、姓名。（10 分）\n（二）若你寫下列 SQL 查詢，請說明電腦會給你什麼結果（假設查詢時，資料庫目前只有上述 9 筆資料）。         （10 分）SELECT Dnumber, COUNT（*）AS High_Sal_Count FROM Employee WHERE Salary > 10000 Group By Dnumber HAVING COUNT（*）> = 2;\n（三）若你寫下列 SQL 查詢，請說明電腦又會給你什麼結果（假設查詢時，資料庫目前只有上述 9 筆資料）          。（10 分）SELECT Dnumber, COUNT（*）AS High_Sal_Count FROM Employee WHERE Salary > 10000 AND Dnumber IN（SELECT Dnumber FROM Employee Group By Dnumber HAVING COUNT（*）> = 2）Group By Dnumber;","pt":30,"warn":["fig","math"]},{"n":3,"q":"關聯式資料庫的設計中，需要關注資料間的功能相依      （Functional Dependency），\n（一）資料間為何有功能相依？如何找到企業中的資料間之功能相依？                 （5 分）\n（二）假設有下列表格 R，已知有五筆資料 t1,t2,t3,t4,t5，由目前已觀察到的資料值，請檢視各個功能相依，來一一回答「已可確認不存在」或「還有可能存在」？為什麼？（15 分）\n⑴A1→A2\n⑵A1→A3\n⑶{A1,A5}→A3\n⑷{A3,A5}→A4\n⑸{A3,A4}→A2 A1   A2   A3   A4   A5 1    2    3   40   60 2    2    4   50   78 1    3    3   40   60 1   11    3   66   70 8   11   33   77   70","pt":20,"ref":"【破題】\n本題測驗關聯式資料庫設計的理論基礎——功能相依（Functional Dependency, FD）。作答第一部分須從真實世界語意限制闡明功能相依的本質與探勘途徑；第二部分則須以給定之資料實例為基礎，依據功能相依定義進行嚴格的反例檢驗，精確判別各相依關係是已確認不存在或可能存在。\n\n【答題架構】\n一、功能相依之成因與企業發掘途徑\n（一）資料間存在功能相依之成因：\n功能相依反映的是現實世界中實體屬性間的語意規則（Data Semantics）與企業業務邏輯約束（Business Rules）。例如每位員工配置唯一員工代碼，則員工代碼即唯一決定其姓名與部門。它是資料庫模式的完整性限制，非隨機數值關係。\n（二）發掘企業資料間功能相依之方法：\n1. 需求訪談與業務流程分析：透過系統分析深入了解企業營運規則與實體關聯。\n2. 檢視現有業務表單與報表：觀察單據中的抬頭、明細與編碼體系（如訂單編號決定客戶與訂單日期）。\n3. 檢驗候選鍵與資料字典：定義實體的超鍵與唯一屬性集合，確立屬性間的單向決定關係。\n4. 注意限制：資料實例的樣本觀察只能用來「推翻」不存在的相依，無法證明相依必然永遠成立，最終仍須回歸業務語意確認。\n\n二、給定表格資料檢視各功能相依（五筆資料檢驗）\n依據定義：若 X 決定 Y（X → Y），則任兩筆資料若 X 值相同，其 Y 值亦必須相同。若出現 X 相同而 Y 不同的反例，即確認不存在。\n（一）檢視 A1 → A2：\n【已可確認不存在】。\n理由：觀察第 1 筆資料 t1(A1=1, A2=2) 與第 3 筆資料 t3(A1=1, A2=3)，兩者 A1 值皆為 1，但 A2 值分別為 2 與 3，產生衝突反例，故該相依已被推翻。\n（二）檢視 A1 → A3：\n【還有可能存在】。\n理由：資料中 A1=1 出現在 t1, t3, t4，其對應的 A3 值全為 3；其餘 A1 值（t2 的 2、t5 的 8）皆未重複。在目前給定樣本中未出現任何反例，故現有資料下有可能存在。\n（三）檢視 {A1, A5} → A3：\n【還有可能存在】。\n理由：屬性組合 {A1, A5} 在樣本中，僅 t1 與 t3 出現重複值 {1, 60}，兩者對應的 A3 值皆為 3；其餘資料組合皆不重複。樣本中無衝突反例，故有可能存在。\n（四）檢視 {A3, A5} → A4：\n【還有可能存在】。\n理由：屬性組合 {A3, A5} 在資料中，僅 t1 與 t3 均為 {3, 60}，對應之 A4 值皆為 40；其餘組合皆互不相同，無任何衝突反例，故有可能存在。\n（五）檢視 {A3, A4} → A2：\n【已可確認不存在】。\n理由：檢視 t1 與 t3，兩者之 {A3, A4} 組合皆為 {3, 40}，但 t1 的 A2 為 2，t3 的 A2 為 3，相同決定屬性對應到不同被決定值，已構成反例，故確認不存在。\n\n【關鍵字】\n功能相依、資料語意、業務規則、反例檢驗、候選鍵、完整性限制、決定屬性\n\n【作答提醒】\n第二小題作答時，格式必須統一明確回答「已可確認不存在」或「還有可能存在」，切勿使用模擬兩可的字眼。對於不存在者，一定要指名具體資料列（如 t1 與 t3）的數值矛盾作為鐵證；對於可能存在者，務必在理由中重申「目前觀察資料無違規反例，但正式成立仍需符合企業業務語意」，以展現深厚的資料庫理論素養。"},{"n":4,"q":"假設某關聯式資料庫，五個屬性值均是 atomic、不可再分割。設計師發現有下列 2 條功能相依，設計出一個資料表 R（A1,A2,A3,A4,A5）FD1：{A1,A3}→A5 FD2：A1→A2\n（一）請問此表格 R 之候選鍵（Candidate Key）有那些？為什麼？（3 分）\n（二）上述設計違反了正規化（Normalization）理論，為什麼？（3 分）\n（三）若資料表改為下列 2 個表格 R1（A1,A4,A5）、R2（A2,A3,A4,A5）（12 分）請你先判定新表格 R1、R2 的候選鍵。這樣的切割，是否滿足 Lossless Join？這樣的切割，是否會喪失任何功能相依？這樣設計最高是滿足第幾正規化，為什麼？\n（四）若你不同意上述（三）設計，你建議應如何修改原設計師所提出資料表 R（A1,A2,A3,A4,A5）？你必須同樣地依上述、、、四方面來說明你建議的設計。（12 分）","pt":30,"warn":["pua"]}]},{"roc":110,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110190&c=342&s=2501&q=1","qs":[{"n":1,"q":"給定一個資料表，PersonIncome，其欄位與資料紀錄如下表，ID 是主鍵，name 是員工姓名，paydate 是員工收到工作費的日期，income 是工作費收入金額。此表總共有 12 筆資料紀錄。請回答下列相關問題：ID     name    paydate     income C1001   王大陸    2008/02/28    25000 C1002   李大喬    2008/03/12    21000 C1003   趙麗生    2008/04/13    27000 C1004   黃球聲    2008/05/15    28000 C1005   王大陸    2009/06/28    27000 C1006   李曉喬    2009/07/12    23000 C1007   趙麗生    2009/08/13    17000 C1008   黃球聲    2010/09/15    25000 C1009   王大陸    2010/10/28    29000 C1010   李大喬    2010/11/12    28000 C1011   趙麗生    2010/12/13    28000 C1012   黃球聲    2011/01/15    27000\n（一）請寫出可查出收入金額大於 22000 或小於 26000 的資料紀錄之 SQL查詢指令。（3 分）\n（二）請寫出可查出收入金額為 7 之倍數的資料紀錄之 SQL 查詢指令。（3 分）\n（三）請寫出可查出名字中包含\"大\"的資料紀錄之 SQL 查詢指令。         （2 分）\n（四）請寫出可得到每個人個別的平均收入之 SQL 查詢指令。（3 分）\n（五）要得到從 2008-05-01 到 2010-12-31 之間每個人個別的收入總額，請寫出對應之 SQL 查詢指令。（4 分）\n（六）要查出收入總額大於 70000 的有那些人，請寫出對應之 SQL 查詢指令。（5 分）","pt":20,"warn":["fig","math"]},{"n":2,"q":"關於物件導向資料庫，請回答下列問題：\n（一）請闡述何謂物件導向資料庫？（3 分）\n（二）有些資料類型適合儲存在物件導向資料庫，請舉出三種適合以物件導向資料庫儲存的資料類型。           （3 分）\n（三）關聯式資料模型有許多構成元素，其中表格（Table）、值組（Row/ Tuple）、主鍵（Primary Key）、屬性（Attribute）、預儲程序（Stored Procedure），這些元素可以分別對應到物件導向資料庫的那些元素？（4 分）\n（四）物件導向資料庫會運用到類別繼承的設計，請闡述繼承的規則。                    （5 分）\n（五）物件導向資料模型也運用到屬性的概念，分成下列四種：基本屬性（Primitive Attribute）、複合屬性（Complex Attribute）、集合屬性（Set、複合集合屬性（Complex Set Attribute）Attribute）                              。請闡述這四種屬性的意涵。（5 分）","pt":20,"ref":"【破題】\n本題測驗物件導向資料庫（OODBMS）的核心概念、適用場景、與關聯式模型之映射對應，以及繼承規則與屬性分類。作答時應把握物件導向「封裝、繼承、多型」與物件識別碼（OID）特性，分五個小題依序分點說明，對應表格建議以清晰文字呈現兩大模型的概念轉換。\n\n【答題架構】\n一、物件導向資料庫（OODBMS）之定義與核心概念：\n（一）定義：結合物件導向程式語言概念與資料庫管理系統技術，將資料及處理資料之行為（方法）共同封裝在物件中進行持久化儲存。\n（二）核心特性：具備獨立於屬性值的物件識別碼（OID）、支援複雜資料型態、封裝性、繼承性與多型性，能有效解決物件導向語言與關聯式資料庫間的阻抗不符（Impedance Mismatch）問題。\n二、適合儲存於物件導向資料庫的三種資料類型：\n（一）多媒體資料：如高解析度影像、影音串流、3D模型，結構複雜且非傳統結構化欄位所能輕易表達。\n（二）電腦輔助設計與製造（CAD/CAM）資料：具備高度巢狀結構、多層次零件組合與複雜工程規格關聯。\n（三）地理資訊系統（GIS）空間資料：包含多邊形、向量拓撲與階層式空間幾何物件。\n三、關聯式資料模型與物件導向資料庫之元素對應：\n（一）表格（Table）：對應至類別（Class）或類別範圍（Class Extent）。\n（二）值組（Row / Tuple）：對應至物件（Object）或類別實例（Instance）。\n（三）主鍵（Primary Key）：對應至物件識別碼（Object Identifier, OID）。\n（四）屬性（Attribute）：對應至物件之屬性、實例變數（Field / Member Variable）。\n（五）預儲程序（Stored Procedure）：對應至方法（Method / Operation）。\n四、類別繼承（Inheritance）之運作規則：\n（一）階層與單一／多重繼承：子類別可繼承父類別的資料結構與操作，單一繼承為單一路徑，多重繼承需處理命名衝突與菱形繼承問題。\n（二）結構與行為擴充：子類別自動獲得父類別所有屬性與方法，並可宣告專屬之新屬性或新方法。\n（三）覆寫與多型機制：子類別可重新定義（Override）父類別的方法實作，透過執行期動態繫結展現多型。\n（四）替換原則：子類別實例在任何使用父類別型態的情境中皆能相容運作。\n五、四種物件屬性之意涵闡述：\n（一）基本屬性（Primitive Attribute）：值為不可分割的原子型態，如整數、浮點數、字串、布林值。\n（二）複合屬性（Complex Attribute）：由多個屬性組合構成的結構化屬性，亦即屬性本身由另一結構或物件定義（例如包含郵遞區號與街道的地址結構）。\n（三）集合屬性（Set Attribute）：屬性值為一組無序且元素不重複的基本型態集合（例如一名員工擁有之專長名稱集合）。\n（四）複合集合屬性（Complex Set Attribute）：屬性值為多個複合結構或物件所構成的集合（例如一名作者發表的多篇論文清單，每篇論文內部皆包含篇名、出版資訊等多元結構）。\n\n【關鍵字】\n物件導向資料庫、阻抗不符、物件識別碼、封裝、繼承、多型、方法、類別範圍、原子型態、複合屬性、集合屬性\n\n【作答提醒】\n第三小題之概念映射是高頻得分點，切勿將主鍵誤對應為一般屬性，其核心差異在於 OID 是系統自動產生且不隨屬性值變更的獨立識別；第四小題說明繼承規則時，務必點出「方法覆寫」與「多型」的關聯，論述才會飽滿完整。"},{"n":3,"q":"資料庫正規化（Normalization）是很重要的資料塑模（Data Modeling）方法，請回答下列相關問題：\n（一）請敘述正規化的目的。（3 分）\n（二）請敘述第一正規化形式（1NF）的規則，並舉一個不符合 1NF 的資料表例子。（4 分）\n（三）請敘述第二正規化形式（2NF）的規則，並舉一個不符合 2NF 的資料表例子。（5 分）\n（四）請敘述第三正規化形式（3NF）的規則，並舉一個不符合 3NF 的資料表例子。（4 分）\n（五）請敘述 BCNF（Boyce-Codd Normal Form）正規化形式的規則。（4 分）","pt":20,"ref":"【破題】\n資料庫正規化是關聯式資料庫設計的基石，旨在透過函數相依理論消除資料重複並避免異常。本題題綱明確涵蓋正規化目標、1NF 至 3NF 及 BCNF 的定義與反例，作答時須依各正規化形式之遞進限制精準定義，並搭配清晰易懂的表格欄位實例說明異常現象與拆解方式。\n\n【答題架構】\n一、資料庫正規化之目的：\n（一）減少資料重複性（Data Redundancy）：降低多餘資料所佔用的儲存空間，避免資料不一致。\n（二）避免資料異動異常（Anomalies）：消除新增異常（無法在未有關聯實體時輸入資料）、刪除異常（刪除某資料時附帶遺失其他必要資訊）與修改異常（修改一筆資料需同步更新多處，否則產生矛盾）。\n（三）增進資料完整性：建立結構穩固之關聯綱要，提升資料庫擴充性與維護性。\n二、第一正規化形式（1NF）規則與實例：\n（一）規則：資料表中的每個欄位屬性值皆必須為不可分割之原子值（Atomic Value），禁止重複群（Repeating Groups）與多值屬性。\n（二）反例：建立學生修課表「學生（學號, 姓名, 修課名稱）」，若某學生的修課名稱欄位填入「資料庫, 作業系統, 演算法」，一個欄位包含多個值，即違反 1NF。修正方式為將每門課程拆分為獨立值組。\n三、第二正規化形式（2NF）規則與實例：\n（一）規則：符合 1NF，且所有非主鍵屬性必須完全函數相依（Fully Functionally Dependent）於複合候選鍵，亦即消除非主鍵屬性對候選鍵的部分函數相依（Partial Functional Dependency）。\n（二）反例：建立選課表「選課（學號, 課程代碼, 學生姓名, 成績）」，主鍵為（學號, 課程代碼）。其中「學生姓名」僅相依於「學號」，未完全相依於整個複合主鍵，違反 2NF。修正方式為拆分為學生表與修課成績表。\n四、第三正規化形式（3NF）規則與實例：\n（一）規則：符合 2NF，且所有非主鍵屬性不得遞移相依（Transitively Dependent）於候選鍵，亦即消除遞移函數相依。\n（二）反例：建立員工表「員工（員工編號, 部門代號, 部門名稱）」，主鍵為員工編號。存在相依關係「員工編號決定部門代號」且「部門代號決定部門名稱」，導致非主鍵屬性部門名稱遞移相依於主鍵員工編號，違反 3NF。修正方式為將部門資訊獨立成部門表。\n五、BCNF（Boyce-Codd Normal Form）規則：\n（一）規則：比 3NF 更為嚴格，要求關聯表中每一個非平庸的函數相依 X -> Y，其決定因素（Determinant）X 都必須是超鍵（Superkey）。\n（二）核心意義：3NF 允許相依目標 Y 為主屬性（候選鍵的一部分），而 BCNF 徹底消除所有非超鍵決定因素所造成的相依，特別適用於存在多個重疊複合候選鍵之複雜關聯表。\n\n【關鍵字】\n正規化、函數相依、部分函數相依、遞移函數相依、原子值、決定因素、超鍵、候選鍵、新增異常、刪除異常、修改異常、BCNF\n\n【作答提醒】\n舉例時務必明確寫出「主鍵」與「函數相依關係」，才能清楚論證為何違反該階段正規化；第五小題說明 BCNF 時，考生常忽略點出「相較於 3NF 允許相依右側為主屬性，BCNF 要求相依左側必須為超鍵」這項關鍵分野，宜特別加強對比說明。"},{"n":4,"q":"在多使用者多工的資料庫管理系統（Database Management System），多個交易（Transactions）在同步執行（Concurrently Performed）時，有可能發生資料讀取之難題（issue）   。請回答下列相關問題：\n（一）請敘述何謂交易？（4 分）\n（二）請敘述何謂更新遺失（Lost Updates）的難題？（4 分）\n（三）請敘述何謂讀到髒資料（Dirty Read）的難題？（4 分）\n（四）請敘述何謂無法重複讀取（Non-Repeatable Read）難題？（4 分）\n（五）同步控制方法（Concurrency Control Method）可運用來解決前述的難題。其中有一種以鎖為基礎之協定（Lock-Based Protocol），請敘述其運作機制。 （4 分）","pt":20},{"n":5,"q":"資料庫領域有許多專門術語，請敘述下列術語之意涵：\n（一）參與限制（Participation Constraint）（4 分）\n（二）基數限制（Cardinality Constraint）（4 分）\n（三） View（4 分）\n（四）外來鍵（Foreign Key）（4 分）\n（五）叢集索引（Clustered Index）（4 分）","pt":20,"ref":"【破題】\n本題測驗資料庫核心領域中涵蓋概念塑模、邏輯綱要與實體儲存等五項基礎關鍵術語。作答時應以簡潔嚴謹的學術定義開展，闡明其背後的系統架構作用，並輔以實務範例，展現全面且紮實的專業底蘊。\n\n【答題架構】\n一、參與限制（Participation Constraint）\n（一）意涵：規範實體集合中的實體參與某個關係集合的程度限制，主要決定實體的存在是否依賴於該關係。\n（二）分類：\n1. 全部參與（Total Participation）：實體集合中的每一個實體都「必須」參與該關係，在實體關係圖中以雙實線表示，亦稱存在相依（Existence Dependency）。例如：圖書館借閱紀錄中的借書讀者。\n2. 部分參與（Partial Participation）：實體集合中僅有部分實體參與該關係，以單實線表示。例如：並非所有館員都會參與借書手續處理。\n\n二、基數限制（Cardinality Constraint）\n（一）意涵：規範在一個關係集合中，一個實體至多（或至少）能夠與另一個實體集合中的幾個實體產生關聯之數量約束。\n（二）表達形式：常見之基數比包含一對一（1:1）、一對多（1:N）與多對多（M:N）。進階實體關係塑模中常以（min, max）結構化數值對精準界定關聯次數之下限與上限。\n\n三、視圖（View）\n（一）意涵：建立在一個或多個基底資料表（Base Tables）或其他視圖之上的「虛擬表格（Virtual Table）」。\n（二）運作機制與優勢：資料庫實體儲存中並不儲存視圖的資料實體（具體化視圖 Materialized View 除外），僅在資料字典中保存其對應之 SQL 查詢陳述句。主要優點包含：強化資料安全性（隱蔽敏感欄位）、簡化終端使用者複雜查詢、維持邏輯資料獨立性（Logical Data Independence）。\n\n四、外來鍵（Foreign Key）\n（一）意涵：關聯式資料庫中某個表格的一個屬性或屬性組合，其數值必須對應參照（Reference）至另一個表格（或同表格自身）的主鍵（Primary Key）或候選鍵（Candidate Key），或者為空值（NULL）。\n（二）系統作用：用以落實與維護關聯式資料庫之「參照完整性限制（Referential Integrity Constraint）」，防止產生孤兒紀錄，並可設定級聯（CASCADE）更新或刪除。\n\n五、叢集索引（Clustered Index）\n（一）意涵：資料庫表格中資料列的「實體儲存順序」與索引鍵值的「邏輯排序順序」完全一致的索引結構。\n（二）特性與應用：\n1. 唯一性限制：由於硬碟或儲存媒介上的資料實體物理排列順序只能有一種，因此一個資料表「至多只能擁有一個」叢集索引（通常預設建構於主鍵之上）。\n2. 效能優勢：對於範圍搜尋（Range Query，如 BETWEEN）與特定欄位排序（ORDER BY）操作具備極高的檢索效率，相較於非叢集索引能大幅減少隨機 I/O 存取次數。\n\n【關鍵字】\n參與限制、全部參與、部分參與、基數限制、基數比、視圖、虛擬表格、邏輯資料獨立性、外來鍵、參照完整性、叢集索引、實體儲存順序、範圍查詢\n\n【作答提醒】\n名詞解釋題切忌單純抄寫直譯字面，每題配分 4 分，作答必須具備「定義＋分類/特性＋實務應用價值」的完整結構。例如寫 View 一定要提到「虛擬表格」與「邏輯資料獨立性」；寫外來鍵一定要提及「參照完整性」；寫叢集索引一定要強調「實體儲存順序一致」且「一張表只能有一個」，方能精準鎖定閱卷核心得分點。"}]},{"roc":109,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109190&c=345&s=2701&q=1","qs":[{"n":1,"q":"在資料模型中，限制（Constraints）是資料庫狀態（Database States）任何時刻必須滿足的條件，請論述實體關聯模型（ER Models）有關實體間對應的兩個限制及關聯模型（Relational Models）的三個限制。另外，關聯資料庫模型如何表示上述實體關聯模型的兩個限制？（20分）","pt":20,"ref":"【破題】\n本題考資料模型的「結構限制」如何從概念層（ER）落實到邏輯層（關聯模型）。先分別定義兩個模型的限制，最後把 ER 的兩個限制逐一對應到關聯模型的實作方式，三段要互相呼應。\n\n【答題架構】\n一、ER 模型中實體間對應的兩個限制（結構限制）\n（一）基數比限制（Cardinality Ratio）：一個實體可與另一實體集中多少個實體相關聯，分 1:1、1:N、M:N，舉例：部門與經理 1:1、部門與員工 1:N、員工與專案 M:N。\n（二）參與限制（Participation Constraint）：全部參與（Total，存在相依，ER 圖以雙線表示）與部分參與（Partial，單線）。可補充 (min, max) 表示法同時涵蓋兩者。\n二、關聯模型的三個限制\n（一）鍵值限制（Key Constraint）：超鍵、候選鍵、主鍵，同一關聯中不得有兩筆值組的鍵值相同；可附帶定義域限制（Domain Constraint）作背景。\n（二）實體完整性限制（Entity Integrity）：主鍵的任何屬性不得為 NULL。\n（三）參考完整性限制（Referential Integrity）：外鍵的值必須對應到被參考關聯中既有的主鍵值，或為 NULL。\n三、關聯模型如何表示 ER 的兩個限制\n（一）基數比：1:1 可將外鍵放在任一方（宜放在全部參與的一方），並加 UNIQUE；1:N 將外鍵放在 N 方；M:N 另建關係表，以雙方主鍵組合為主鍵，兩欄皆為外鍵。\n（二）參與限制：全部參與以外鍵欄位 NOT NULL 表示；部分參與則允許 NULL。若全部參與在「1」方（每個部門至少有一名員工），僅靠外鍵無法表達，需以觸發程序（Trigger）或斷言（Assertion）補強。\n（三）可順帶說明參考動作 ON DELETE / ON UPDATE（CASCADE、SET NULL、RESTRICT）維護完整性。\n\n【關鍵字】\n結構限制、基數比、參與限制、全部參與、部分參與、存在相依、鍵值限制、實體完整性、參考完整性、定義域限制、外鍵、NOT NULL、UNIQUE、觸發程序、斷言、Elmasri 與 Navathe\n\n【作答提醒】\n1. 第三小題才是區分高下的地方，務必逐一對應 1:1、1:N、M:N 與全部／部分參與，並各舉一例。\n2. 指出「外鍵 NOT NULL 只能表達 N 方的全部參與」這個限制，能展現深度。\n3. 可畫小型 ER 圖與轉換後的綱要對照，閱卷較易給分。"},{"n":2,"q":"一家公司 Company 的資料，擬設計一資料庫來儲存，經系統分析後，得到如下需求： Company 公司由許多部門（department）組成，每一部門有一部門代碼（dept-id） 、一部門名稱（dept-name）   ，一部門會有多個地點（dept- loc ）， 每 一 部 門 有 一 員 工 擔 任 主 管 ， 並 記 錄 開 始 擔 任 主 管 日 期（start_date），部門代碼可區別不同部門；一個部門可以承接許多計畫（project），但一計畫僅由一部門承接，每一計畫有計畫代碼（proj-id）              、名稱（proj-name）及計畫說明（proj-descript）  ，計畫代碼可區別不同計畫。一部門由許多員工（employee）組成，每一員工有員工代碼（emp-id）               、員工姓名（emp-name）   、員工性別（emp-sex）與員工生日（emp-birthdate）每一員工隸屬於一部門，每一員工代碼可區別不同員工。員工會互相監督（supervision），每位員工最多有一位直屬監督者，但可能會直接監督多位其他員工。一員工可以扶養多位眷屬（dependent）        ，每一眷屬有眷屬代碼（dep-id）     、眷屬姓名（dep-name）與眷屬生日（dep-birthdate）     ，但一眷屬只能由一員工來扶養。一員工可以參與許多計畫，一計畫也可許多員工來參與，每一員工參與的計畫有一參與的時數（hours）。請劃出 Company 公司實體關聯綱要（Entity-Relationship Schema）  ，包括屬性（Attributes）、實體型態、關聯型態與相關限制。           （20分）","pt":20,"warn":["pua"]},{"n":3,"q":"在資料庫的實作及環境中，同步控制（Concurrency Control）在交易（Transactions）處理是很重要的技術，請論述兩階段鎖定（Two-phase Locking）與時戳（Timestamps）技術及其不同處。（20分）","pt":20,"ref":"【破題】\n同步控制的目的是讓交錯執行的交易產生可序列化（Serializable）的結果。兩階段鎖定屬悲觀式、以鎖定決定順序；時戳屬以交易開始時間預先決定序列順序。作答先各自說明機制，再用比較表收尾。\n\n【答題架構】\n一、同步控制的必要性\n簡述遺失更新、讀取未提交資料（Dirty Read）、不正確彙總等問題，帶出可序列化目標。\n二、兩階段鎖定（2PL）\n（一）鎖的種類：共享鎖（讀鎖）、互斥鎖（寫鎖）與相容矩陣。\n（二）兩階段：成長階段只能取得鎖不能釋放；縮減階段只能釋放不能再取得；分界點為鎖點（Lock Point）。保證衝突可序列化，序列順序即鎖點順序。\n（三）變形：基本 2PL、保守式 2PL（事先取得全部鎖，無死結）、嚴格 2PL（寫鎖到提交才放，避免連鎖回復）、嚴謹 2PL（所有鎖到提交才放）。\n（四）缺點：可能死結與飢餓，需搭配等待圖偵測，或 wait-die、wound-wait 預防。\n三、時戳排序（Timestamp Ordering）\n（一）每筆交易開始時給唯一遞增時戳 TS(T)；每個資料項目記錄 read_TS(X) 與 write_TS(X)。\n（二）讀：若 write_TS(X) > TS(T) 則中止 T，否則允許並更新 read_TS。寫：若 read_TS(X) 或 write_TS(X) > TS(T) 則中止 T，否則允許並更新 write_TS。\n（三）不使用鎖，故不會死結；但可能大量中止重啟、連鎖回復，可用嚴格時戳排序或 Thomas 寫入規則改良。\n四、兩者不同處（建議列表）\n序列順序決定時點（鎖點 vs. 交易開始）、是否有鎖、死結（可能 vs. 不會）、衝突處理（等待 vs. 中止重啟）、額外負擔（鎖表 vs. 每項目兩個時戳）、適用情境（高衝突 vs. 低衝突、讀多寫少）。\n\n【關鍵字】\n可序列化、衝突可序列化、共享鎖、互斥鎖、成長階段、縮減階段、鎖點、保守式 2PL、嚴格 2PL、死結、飢餓、等待圖、wait-die、wound-wait、時戳排序、read_TS、write_TS、Thomas 寫入規則、連鎖回復\n\n【作答提醒】\n1. 時戳的讀寫判斷規則要寫完整，是最容易被扣分的地方。\n2. 比較段用表格呈現，至少列四項差異。\n3. 可舉兩筆交易的排程例子示範 2PL 如何等待、時戳如何中止。"},{"n":4,"q":"現在的臉書與 line 有大量的資料，如應用人工智慧來發掘（Discover）相關關鍵詞，以便了解親友對產品的偏好，其中需要很大量資料來當作訓練與測試資料，以訓練出好的學習模型（Learning Models）    ，請寫出資料庫設計過程（Database Design Process），設計資料庫以儲存臉書與 line 的大量資料（特別留意臉書與 line 資料庫特性）        ，並論述每一過程。（20分）","pt":20,"ref":"【破題】\n本題以社群平台的巨量資料為情境，考標準的資料庫設計流程，並要求點出臉書與 LINE 資料的特性（巨量、高速、多樣、半結構化、圖狀關係），說明每個階段因此需做的選擇。\n\n【答題架構】\n一、情境資料特性分析\n巨量（Volume）、高速（Velocity，貼文訊息即時產生）、多樣（Variety，文字、圖片、影片、貼圖、按讚）、好友關係為圖結構、讀寫量極大、需高可用與水平擴充；作為 AI 訓練資料還需保留標註、時間與版本。\n二、資料庫設計過程與論述\n（一）需求蒐集與分析：訪談使用者，界定資料需求（使用者、貼文、留言、按讚、好友、群組、訊息、關鍵詞標註）與功能需求（關鍵詞擷取、偏好分析、訓練測試資料切分），並考量個資保護與授權。\n（二）概念設計：以 ER 或 EER 圖建立高階模型，例如使用者—好友（遞迴 M:N）、使用者—貼文（1:N）、貼文—關鍵詞（M:N）、使用者—產品偏好；此階段與 DBMS 無關。\n（三）DBMS 選擇：依特性評估。交易性帳號資料可用關聯式資料庫；巨量貼文、訊息適合 NoSQL，例如文件式、寬欄式、鍵值式；好友網路適合圖形資料庫；可採多種資料庫並存（Polyglot Persistence），搭配分散式檔案系統或資料湖存放原始資料供訓練。\n（四）邏輯設計（資料模型對應）：將概念模型轉為選定 DBMS 的綱要，關聯部分做正規化；NoSQL 部分依查詢模式設計，常採反正規化與內嵌文件。\n（五）實體設計：分割（Sharding）、複寫、索引、壓縮、冷熱資料分層，以及依時間分區方便切出訓練集與測試集。\n（六）實作與調校：建立綱要、匯入資料、ETL 清理與標註，監控效能並持續調校。\n三、小結\n強調一致性與可用性的取捨（CAP 定理、BASE 與 ACID），以及資料治理與隱私。\n\n【關鍵字】\n需求分析、概念設計、ER 模型、邏輯設計、實體設計、DBMS 選擇、巨量資料 3V、半結構化資料、NoSQL、文件式資料庫、圖形資料庫、分散式資料庫、Sharding、複寫、反正規化、CAP 定理、BASE、資料湖、ETL、訓練集、測試集\n\n【作答提醒】\n1. 每個階段都要扣回臉書與 LINE 的特性，只背通用流程會失分。\n2. 可畫簡單 ER 圖示範概念設計，提升具體性。\n3. 提到個資保護與使用者授權，展現完整考量。"},{"n":5,"q":"在關聯式資料庫模型，何謂關聯代數（Relational Algebra）？為何需要關聯代數？何謂關聯完全（Relationally Complete）？又商業化的資料庫管理系統會用到的資料庫查詢語言是什麼？與關聯代數有何關係？資料庫處理器（Run-time Database Processor）如何處理此查詢語言？（20分）","pt":20,"ref":"【破題】\n本題串連查詢處理的理論與實務：關聯代數是關聯模型的形式化查詢語言，也是 SQL 被 DBMS 內部轉換、最佳化與執行的基礎。依題目六個問句依序作答。\n\n【答題架構】\n一、何謂關聯代數\n由 Codd 提出的程序式（Procedural）形式查詢語言，以關聯為運算元、結果仍為關聯（封閉性）。基本運算：選擇 σ、投影 π、聯集 ∪、差集 −、卡氏積 ×、更名 ρ；衍生運算：交集、合併（Join、自然合併）、除法。\n二、為何需要關聯代數\n（一）提供關聯模型查詢的形式化基礎與語意定義。\n（二）作為 DBMS 內部查詢表示法，可依代數等價規則改寫並最佳化。\n（三）作為衡量其他查詢語言表達能力的標準。\n三、何謂關聯完全\n一個查詢語言若能表達所有關聯代數（或等價的安全關聯演算）可表達的查詢，即稱為關聯完全。基本運算集合為完備集合。SQL 是關聯完全，且另有彙總、分組、排序等延伸能力。\n四、商業 DBMS 的查詢語言與其關係\n商業 DBMS 使用 SQL。SQL 屬宣告式（Declarative），語法源於關聯演算，SELECT 對應投影、WHERE 對應選擇、FROM 多表對應卡氏積或合併；但 SQL 採多重集合（允許重複值組）而非純集合。\n五、資料庫處理器如何處理 SQL\n（一）掃描與剖析：檢查語法並建立剖析樹。\n（二）驗證：對照系統目錄確認表格與欄位存在、權限。\n（三）轉換為內部表示：查詢樹或關聯代數運算式。\n（四）查詢最佳化：啟發式規則（選擇與投影下推、先做限制性高的運算）與成本估計，選擇存取路徑與合併演算法，產生執行計畫。\n（五）程式碼產生，由執行期資料庫處理器執行計畫、存取儲存資料並回傳結果，同時與同步控制及回復子系統互動。\n\n【關鍵字】\n關聯代數、Codd、選擇、投影、卡氏積、合併、除法、封閉性、程序式語言、宣告式語言、關聯演算、關聯完全、SQL、多重集合、查詢樹、查詢最佳化、啟發式最佳化、成本估計、執行計畫、系統目錄\n\n【作答提醒】\n1. 題目六個問句都要有明確對應段落，漏答任一個都扣分。\n2. 可用一個簡單 SQL 示範轉成關聯代數式與查詢樹。\n3. 點出 SQL 為多重集合語意是加分細節。"}]},{"roc":108,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108190&c=342&s=2901&q=1","qs":[{"n":1,"q":"假 設 我 們 要 設 計 某 物 流 公 司 的 資 料 庫 ， 其 中 某 事 實 是 記 錄 其 司 機（Driver）每天使用某輛卡車（Truck）負責某趟運送（Delivery）。每趟運送剛好用到一部卡車；但出車時，有時會有雙司機出勤，輪流駕駛。司機有編號（ID）、姓名（Name）、薪水（Salary）的資料，卡車有牌照號碼（License_No）、品牌（Make）、款式（Model）、噸數（Tonnage）的 資 料 ， 運 送 有 運 送 編 號 （ D_Number ）、 日 期 （ Date ）、 送 達 地 址（Address）、送達時間（Time）、載送內容（Content）的資料。圖一為實體關係圖（Entity-Relationship Diagram）。對所用符號的約略說明：其中每一實體鄰近某關係間均有一個對應比率（min,max）                ，代表該實體參與該關係之 min（至少）     、max（至多）次數，＊代表沒有限制。屬性劃實底線者為 Primary Key（主鍵）     。請暫時不考慮其他實體、屬性，並假設所有對應比率均為正確反映該企業實況。欲記錄上述事實：\n（一）請說明圖一的設計有何問題？（5 分）\n（二）可否將圖一改為只有司機（Driver）與卡車（Truck）兩個實體，而將運送（Delivery）放在其中、當成關係？這樣的設計有何問題？（8 分）\n（三）請提出改進版本。請注意：你的改進版本必須同時滿足「提供完整（Complete）的資訊，且無多餘的（Redundant）關係」的要求。             （12 分）圖一","pt":25,"warn":["fig"]},{"n":2,"q":"假設關連式資料庫包含下列三個表格：Student（SID, Name, Address, Phone, Major）代表學生學號、姓名、地址、電話、主修Course（CNo, CName, Credit, Dept, Instructor）代表課程編號、名稱、學分數、開課系所、授課教師Grade（SNo, CNo, Score）代表 SNo 的學號學生修習 CNo 的課程得分（0-100 分）「主修」    、「開課系所」之內容值可為 MIS、CS、Business 等，分別代表資管系、資科系、企管系等。\n（一）為教師’王大維’，依課程編號、名稱，列出其授課的每門課之修課人數（8 分）\n（二）找出其所修的每科成績均至少為 90 分之資管系學生姓名。                     （8 分）\n（三）找出在企管系所開所有課程中沒有一科及格過之學生姓名及其主修。 （註：及格分數為 60 分）           （9 分）","pt":25,"ref":"【破題】\n本題為 SQL 實作題，三小題分別考分組計數、全稱條件（每科都≥90）與除法類查詢。作答時寫出完整 SQL，並簡短說明邏輯。\n\n【答題架構】\n一、（一）教師王大維每門課的修課人數\nSELECT C.CNo, C.CName, COUNT(G.SNo) AS 修課人數\nFROM Course C LEFT JOIN Grade G ON C.CNo = G.CNo\nWHERE C.Instructor = '王大維'\nGROUP BY C.CNo, C.CName;\n說明：用 LEFT JOIN 讓無人修的課顯示 0；GROUP BY 欄位須包含 SELECT 中的非彙總欄位。\n二、（二）每科成績均≥90 的資管系學生\nSELECT S.Name FROM Student S JOIN Grade G ON S.SID = G.SNo\nWHERE S.Major = 'MIS'\nGROUP BY S.SID, S.Name\nHAVING MIN(G.Score) >= 90;\n亦可用 NOT EXISTS（不存在該生成績 < 90 的紀錄）寫，但要另加 EXISTS 排除沒修課的學生。\n三、（三）企管系所開所有課程中沒有一科及格的學生\n解讀為「修了企管系開的全部課程，且每一科都不及格」，屬關聯除法，用雙重 NOT EXISTS：\nSELECT S.Name, S.Major FROM Student S\nWHERE NOT EXISTS (\n SELECT * FROM Course C WHERE C.Dept = 'Business'\n AND NOT EXISTS (\n  SELECT * FROM Grade G\n  WHERE G.SNo = S.SID AND G.CNo = C.CNo AND G.Score < 60));\n說明：內層要求每門企管課都有該生「不及格」的紀錄。若解讀為「修過企管課但都沒及格」，則改為 EXISTS 修過企管課，且 NOT EXISTS 企管課 Score >= 60，並在答案中說明採用的解讀。\n\n【關鍵字】\nGROUP BY、COUNT、LEFT JOIN、HAVING、MIN、NOT EXISTS、EXISTS、關聯除法、雙重否定、相關子查詢\n\n【作答提醒】\n1. 第三小題題意有歧義，先寫明自己的解讀再作答，可兩種都寫。\n2. 注意 Student 用 SID、Grade 用 SNo，連結條件別寫錯欄位名。\n3. 全稱條件題要處理「沒修任何課」的邊界情形。"},{"n":3,"q":"假設某資料庫管理系統採用時間戳記（Timestamp）來管理並行控制（Concurrency Control），它採用的不是基本的時間戳記排序，而是修改版的 Thomas 的編寫規則（Write Rule）。假設某交易 T 的時間戳記是10010，請問下列情況，資料庫管理系統會如何處理？（每小題 5 分，共 20 分）\n（一）欲寫某項目 X 時，得知 X 已有寫的時間戳記 write_TS（X）是 10015\n（二）欲寫某項目 X 時，得知 X 已有讀的時間戳記 read_TS（X）是 10012\n（三）欲讀某項目 X 時，得知 X 已有寫的時間戳記 write_TS（X）是 10020\n（四）欲讀某項目 X 時，得知 X 已有寫的時間戳記 write_TS（X）是 10005","pt":20,"ref":"【破題】\nThomas 寫入規則是時戳排序的改良：對「過時的寫入」直接忽略而不中止交易，可接受部分非衝突可序列化但為觀點可序列化的排程。本題 TS(T)=10010，逐小題套用讀寫規則判斷。\n\n【答題架構】\n一、先列規則\n（一）寫入 write_item(X)：若 read_TS(X) > TS(T)，中止並回復 T；若 write_TS(X) > TS(T)，忽略此寫入、T 繼續執行（Thomas 規則重點）；否則執行寫入，令 write_TS(X)=TS(T)。\n（二）讀取 read_item(X)：若 write_TS(X) > TS(T)，中止並回復 T；否則執行讀取，令 read_TS(X)=max(read_TS(X), TS(T))。讀取規則與基本時戳排序相同。\n二、（一）寫 X，write_TS(X)=10015 > 10010\n在 read_TS(X) 不大於 10010 的前提下，表示較新交易已寫過 X，T 的寫入已過時，系統忽略此寫入，T 不中止、繼續執行。若基本時戳排序則會中止 T，可對比說明。\n三、（二）寫 X，read_TS(X)=10012 > 10010\n較新的交易已讀到 X 的舊值，若 T 再寫入會破壞序列順序，故中止並回復 T，之後以新時戳重新啟動。\n四、（三）讀 X，write_TS(X)=10020 > 10010\nT 要讀的值已被較新交易覆寫，T 讀不到應讀的版本，故中止並回復 T，以新時戳重啟。\n五、（四）讀 X，write_TS(X)=10005 ≤ 10010\n允許讀取，並將 read_TS(X) 更新為 max(原值, 10010)。\n\n【關鍵字】\n時戳排序、Thomas 寫入規則、read_TS、write_TS、過時寫入、忽略寫入、中止、回復、重新啟動、觀點可序列化、衝突可序列化\n\n【作答提醒】\n1. 每小題要寫出判斷條件、處置結果與時戳更新三件事。\n2. 第一小題要註明先檢查 read_TS，再判斷 write_TS，順序寫反會被扣分。\n3. 可補一句：被中止的交易重啟時取得新時戳。"},{"n":4,"q":"假 設 某 關 連 式 資 料 庫 有 下 列 表 格 R ， 目 前 僅 有 的 四 筆 資 料 分 別 是t1,t2,t3,t4。沒有人告訴我們各屬性的相互關係，不過，從我們觀察到資料，可以確認有些功能相依是不存在的，還有些功能相依是有可能存在。請說明那些是可確認不存在？那些是有可能存在？答案必須以你觀察到的現象為理由來說明，只憑猜測是不計分。\n（一）（18 分）（1）{D,E} → C（2）{A,B} → D（3）{E,F} → G A     B      C      D      E      F      G a1    b1     c1     d1     e1     f1     g1 a1    b2     c2     d2     e2     f2     g2 a2    b2     c2     d3     e1     f1     g3 a3    b3     c4     d3     e1     f4     g1\n（二）假設已知下列功能相依，請利用功能相依推演規則，也就是 Closure概念，找出所有 R 的候選鍵（Candidate Key），注意：只憑猜測，沒有使用功能相依的推演過程，不計分。（12 分）FD1： {A, E} → {B, G} FD2： C → F FD3： D → C FD4： G → D","pt":30,"warn":["math"]}]},{"roc":107,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107190&c=337&s=2801&q=1","qs":[{"n":1,"q":"（一）目前人工智慧廣泛應用於如製造業、醫療、食衣住行及賦稅等領域，其中需要很大量資料來當作訓練及測試資料，以訓練出好的學習模型（Learning Model），如你／妳被委以建立資料庫來儲存這些大量資料的工作，請寫出資料庫設計的階段（Phases of Database Design）  ，並說明之。  （12 分）\n（二）如果資料庫設計階段決定採用關聯式資料庫模型（Relational Database Model），請寫出四項‟好”的關聯式資料庫設計的關聯式綱要（Relation Schemas）設計原則（Principles or Guidelines）。（8 分）","pt":20,"ref":"【破題】\n第一小題考資料庫設計六階段，需結合 AI 訓練資料的特性；第二小題考 Elmasri 與 Navathe 提出的關聯綱要非正式設計準則。兩題分數 12 與 8 分，篇幅照比例配置。\n\n【答題架構】\n一、（一）資料庫設計的階段\n先點出 AI 訓練資料特性：量大、多樣（結構化感測紀錄、影像、文字）、需標註、需版本與來源追溯、需切分訓練集與測試集。\n（一）需求蒐集與分析：確認各領域資料來源、標註需求、存取量、保存期限與隱私法規。\n（二）概念設計：以 ER 或 EER 模型描述資料集、樣本、標註、標註者、模型版本、實驗結果等實體及關係，與 DBMS 無關。\n（三）DBMS 選擇：結構化資料用關聯式，影像影音等非結構化可用物件儲存搭配 NoSQL 或資料湖，考量擴充性與成本。\n（四）邏輯設計（資料模型對應）：轉換為選定 DBMS 的綱要，關聯部分正規化。\n（五）實體設計：索引、分割、壓縮、分散儲存，依資料集版本或時間分區以利抽樣。\n（六）實作與調校：建立綱要、ETL 匯入與清理、效能監控、持續調整。\n二、（二）好的關聯綱要設計準則\n準則一：語意清楚，每個關聯只表達一種實體或關係，不混合多種概念。\n準則二：避免插入、刪除、修改異常（更新異常）。\n準則三：盡量減少值組中的 NULL 值，常為 NULL 的屬性另立關聯。\n準則四：避免產生虛假值組（Spurious Tuples），分解須具無損合併性質，合併條件應建立在主鍵與外鍵上。\n可補充：以正規化（3NF、BCNF）落實上述準則，並考量相依保持。\n\n【關鍵字】\n需求分析、概念設計、ER 模型、DBMS 選擇、邏輯設計、實體設計、實作與調校、資料湖、ETL、訓練集、測試集、語意清楚、更新異常、插入異常、刪除異常、NULL 值、虛假值組、無損合併、正規化\n\n【作答提醒】\n1. 第一小題要扣回 AI 大量資料情境，只寫通用流程不易拿高分。\n2. 第二小題四項準則名稱要準確，最好各舉一個反例。\n3. 時間配置約依配分 3:2。"},{"n":2,"q":"給予如下（一）與（二）實體關係（Entity-Relationship, ER）圖，其中‟works-for”關係型態（Relationship Types）描述一個部門有許多員工，但一個員工只能屬於某一部門，一個部門可位於多個地方；‟works-on”關係型態（Relationship Types）描述一個員工可以參與多個計畫，一個計畫也可以由多個員工參與，並記錄每一員工參與每一計畫的時間；請將之轉換成關聯式資料庫綱要（Relational Database Schemas）。\n（一）                                     （7 分）\n（二）                                          （7 分）\n（三）在 ER 概念模型有參與限制（Participation Constraints），請問選擇性（Optional）與必須（Mandatory）限制，在關聯式資料庫模型如何表示上述限制。    （6 分）","pt":20},{"n":3,"q":"給予如下兩個關聯綱要（Relation Schemas）及其內容，EMPLOYEE 關聯記錄員工編號、薪水及所在部門，DEPARTMENT 關聯記錄部門編號及 名 稱 ， 其 中 EMPLOYEE 的 外 來 鍵 （ Foreign Key ） ‟dno” 參 考 到DEPARTMENT 的主鍵（Primary Key）‟dnum”，執行下列⑴與⑵的 SQL查詢後的結果分別為何？其意義分別為何？（20 分）EMPLOYEE ssn     salary   dno 1      30000     5 2      40000     5 3      38000     5               DEPARTMENT 4      25000     5          dnum          dname 5      25000     4            1       R&D 6      43000     4            2       Administration 7      25000     4            3       Accounting 8      55000     1            4       Finances 9      45000     1            5       Personnel 10      30000     1 11      50000     2 12      25000     2 13      30000     3\n⑴SELECT dno, COUNT(*) FROM DEPARTMENT, EMPLOYEE WHERE dnum = dno AND salary > 25000 GROUP BY dno HAVING COUNT(*) > 2\n⑵SELECT dno, COUNT(*) FROM DEPARTMENT, EMPLOYEE WHERE dnum = dno AND salary > 25000 AND dno IN (SELECT dno FROM EMPLOYEE GROUP BY dno HAVING COUNT(*) > 2) GROUP BY dno","pt":20,"warn":["math"]},{"n":4,"q":"給予一關聯綱要 R(A, B, C, D, E, F)及一組功能依附性（Functional Dependencies）F = {{A}→{B, C, D, E, F}, {B, C}→{A, D, E, F}, {B}→{F}, {D}→{E}}，請將 R 分別分割（Decompose）成 2NF 及 3NF 的關聯綱要。（20 分）","pt":20,"ref":"【破題】\n正規化題先求候選鍵、區分主鍵屬性與非主鍵屬性，再依序消除部分相依（2NF）與遞移相依（3NF）。本題重點在於 B 是候選鍵 {B,C} 的一部分，B→F 構成部分相依。\n\n【答題架構】\n一、求候選鍵\n（一）A+ = {A,B,C,D,E,F}，A 為候選鍵。\n（二）{B,C}+：由 BC→ADEF 得全部屬性，且 B+ = {B,F}、C+ = {C} 都不是全部，故 {B,C} 為最小，亦為候選鍵。\n（三）主鍵屬性：A、B、C；非主鍵屬性：D、E、F。\n二、檢查 1NF 至 2NF\n（一）2NF 要求非主鍵屬性完全功能相依於每個候選鍵。\n（二）B→F：F 只相依於候選鍵 {B,C} 的部分 B，為部分相依，違反 2NF。\n（三）D→E 不是對鍵的部分相依，不影響 2NF。\n（四）2NF 分解：R1(B, F)，主鍵 B；R2(A, B, C, D, E)，主鍵 A，候選鍵 {B,C}，B 為參考 R1 的外鍵。\n三、分解為 3NF\n（一）3NF 要求非主鍵屬性不得遞移相依於鍵；R2 中 A→D、D→E，E 遞移相依於 A，違反 3NF。\n（二）分解：R21(D, E)，主鍵 D；R22(A, B, C, D)，主鍵 A，候選鍵 {B,C}，D 為外鍵。\n（三）3NF 結果：R1(B, F)、R21(D, E)、R22(A, B, C, D)。\n四、驗證\n每次分解的共同屬性（B、D）皆為其中一方的鍵，故為無損合併；原有功能相依 A→BCDEF、BC→ADEF 可由 R22 與 R1、R21 推得，B→F、D→E 各自保留，具相依保持。\n\n【關鍵字】\n功能相依、屬性閉包、候選鍵、主鍵屬性、非主鍵屬性、部分相依、完全功能相依、遞移相依、2NF、3NF、無損合併分解、相依保持\n\n【作答提醒】\n1. 一定要先求出兩個候選鍵，漏掉 {B,C} 就看不出 B→F 是部分相依。\n2. 每步寫出違反的相依與理由，不要只列結果。\n3. 結尾驗證無損合併與相依保持是加分項。"},{"n":5,"q":"（一）分散式資料庫系統的優點是擁有透明度（Transparency），請寫出三種分散式資料庫的透明度並說明之。      （8 分）\n（二）為確保資料庫交易（Transactions）能正確被執行，資料庫管理系統（DBMS）的並行控制（Concurrency Control）與回復方式（Recovery Methods）應具備那四項特性（Properties）？請說明之。（12 分）","pt":20,"ref":"【破題】\n第一小題考分散式資料庫的透明度，讓使用者像使用單一集中式資料庫；第二小題考交易的 ACID 四特性，並連結由並行控制與回復機制分別負責哪幾項。\n\n【答題架構】\n一、（一）分散式資料庫的透明度（擇三說明，可多寫）\n（一）分散或位置透明（Location Transparency）：使用者不需知道資料存放在哪個站台，查詢時不必指定位置；命名透明為其相關概念。\n（二）分割透明（Fragmentation Transparency）：資料被水平或垂直分割到不同站台，使用者仍以整體關聯查詢，系統自動組合。\n（三）複製透明（Replication Transparency）：同一資料在多站台存有副本以提升可用性與效能，使用者不必知道副本存在，系統負責副本一致。\n補充：網路透明、交易透明、失效透明、異質透明。\n二、（二）交易的 ACID 特性\n（一）單元性（Atomicity）：交易內的操作要嘛全部完成、要嘛全部不做；由回復子系統以日誌執行 Undo 確保。\n（二）一致性（Consistency）：交易執行前後資料庫皆符合完整性限制；主要由程式設計者與 DBMS 的完整性檢查保障。\n（三）隔離性（Isolation）：並行執行的交易彼此不互相干擾，效果如同依序執行；由並行控制（鎖定、時戳、多版本）達成，SQL 定義隔離等級。\n（四）持久性（Durability）：交易一旦提交，其結果永久保存，即使系統故障也不遺失；由回復子系統以日誌、先寫日誌（WAL）、Redo 與檢查點確保。\n三、小結\n並行控制主要負責隔離性，回復方法主要負責單元性與持久性，兩者共同維護一致性；分散式環境另需兩階段提交（2PC）確保跨站台交易的單元性。\n\n【關鍵字】\n位置透明、分割透明、複製透明、命名透明、水平分割、垂直分割、網路透明、ACID、單元性、一致性、隔離性、持久性、日誌、先寫日誌、Undo、Redo、檢查點、隔離等級、兩階段提交\n\n【作答提醒】\n1. ACID 每項都要說明由哪個子系統負責，這是第二小題的得分關鍵。\n2. 透明度至少寫三種並各舉例，配分 8 分不宜寫太長。\n3. 結尾提兩階段提交可連結兩小題。"}]},{"roc":106,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=106190&c=336&s=2501&q=1","qs":[{"n":1,"q":"請試述下列名詞之意涵：（每小題 5 分，共 20 分）\n（一）Entity Integrity Rule\n（二）Location independence in a distributed database\n（三）SSA: Segment Search Arguments in the Hierarchical Database Model\n（四）Two Phase Locking Protocol（每小題 5 分，共 20 分）","pt":20,"ref":"【破題】\n四個名詞橫跨關聯模型、分散式資料庫、階層式模型與同步控制，每小題 5 分，各寫定義、運作方式、用途或例子三層即可。\n\n【答題架構】\n一、（一）Entity Integrity Rule（實體完整性規則）\n定義：關聯中主鍵的任何屬性都不可為 NULL。理由：主鍵用來唯一識別值組，NULL 代表未知，無法識別實體。與參考完整性並列為關聯模型的完整性規則；SQL 中宣告 PRIMARY KEY 即自動隱含 NOT NULL 與唯一。舉例：Student 的學號不可空白。\n二、（二）Location Independence（位置獨立性）\n定義：分散式資料庫中，使用者存取資料時不需知道資料實際存放的站台，也就是位置透明。資料搬移站台時應用程式不必修改。由全域目錄（Global Catalog）與命名機制支援。可提及 C. J. Date 的分散式資料庫目標中將其列為重要目標，並與分割獨立性、複製獨立性一同說明。\n三、（三）SSA（區段搜尋參數）\n階層式資料模型（以 IBM IMS 為代表）以樹狀結構組織區段（Segment），使用 DL/I 語言存取。SSA 附在 DL/I 指令（如 GU、GN、GNP）中，指定要搜尋的區段型態名稱，並可帶條件，例如 欄位名 比較運算子 值。分為不帶條件（Unqualified SSA，只寫區段名）與帶條件（Qualified SSA）。多個 SSA 由根區段往下沿階層路徑定位目標區段。\n四、（四）Two Phase Locking Protocol（兩階段鎖定協定）\n交易的鎖定分為成長階段（只取得鎖）與縮減階段（只釋放鎖），一旦釋放任何鎖便不得再取得新鎖。可保證排程衝突可序列化。變形有保守式、嚴格、嚴謹 2PL；缺點為可能發生死結，需死結偵測或預防。\n\n【關鍵字】\n實體完整性、主鍵、NULL、參考完整性、位置獨立性、位置透明、全域目錄、分散式資料庫、階層式模型、IMS、DL/I、區段、Qualified SSA、Unqualified SSA、GU、GN、兩階段鎖定、成長階段、縮減階段、可序列化、死結\n\n【作答提醒】\n1. 每小題配分相同，篇幅平均，別在熟悉的 2PL 寫太多。\n2. SSA 較冷門，至少寫出所屬模型、用途與兩種類型。\n3. 中英文名詞並列，閱卷較易辨識。"},{"n":2,"q":"一個大學課程關聯資料庫包含下列關係：STUDENT(S#, Sname, Saddress, D#), TEACHER(T#, Tname, Taddress, D#), COURSE(C#, Cname, CreditHour), TAKE_COURSE(S#, C#, Score), OFFER(T#, C#, Classroom)寫出下列查詢的 SQL 描述：\n（一）找出學生姓名與其曾經修過某位老師剛好兩門課的老師姓名\n（二）找出從來沒有被當過（所有課程 Score ≧60）的學生姓名\n（三）找出修過名稱為‘John’開設所有課程並且都被當掉的學生\n（四）列出所有學生的姓名與總學分數（CreditHour）與修過課程的平均分數","pt":0,"ref":"【破題】\n本題為 SQL 查詢實作，四小題分別考多表合併加分組計數、全稱條件、關聯除法與彙總函數。欄位名含 # 號，作答時可說明實作上需以引號或改名處理（以下沿用題目名稱）。\n\n【答題架構】\n一、（一）學生與其修過剛好兩門課的老師\nSELECT S.Sname, T.Tname\nFROM STUDENT S JOIN TAKE_COURSE TC ON S.S# = TC.S#\nJOIN OFFER O ON TC.C# = O.C#\nJOIN TEACHER T ON O.T# = T.T#\nGROUP BY S.S#, S.Sname, T.T#, T.Tname\nHAVING COUNT(DISTINCT TC.C#) = 2;\n說明：TAKE_COURSE 未記錄授課老師，若同一門課由多位老師開設會有歧義，答題時註明假設每門課由一位老師開授。\n二、（二）從未被當的學生\nSELECT S.Sname FROM STUDENT S\nWHERE EXISTS (SELECT * FROM TAKE_COURSE TC WHERE TC.S# = S.S#)\nAND NOT EXISTS (SELECT * FROM TAKE_COURSE TC WHERE TC.S# = S.S# AND TC.Score < 60);\n說明：EXISTS 用來排除沒修任何課的學生，是否排除可說明假設。\n三、（三）修過 John 開的所有課且全部被當\nSELECT S.Sname FROM STUDENT S\nWHERE NOT EXISTS (\n SELECT * FROM OFFER O JOIN TEACHER T ON O.T# = T.T#\n WHERE T.Tname = 'John'\n AND NOT EXISTS (\n  SELECT * FROM TAKE_COURSE TC\n  WHERE TC.S# = S.S# AND TC.C# = O.C# AND TC.Score < 60));\n說明：雙重 NOT EXISTS 表達關聯除法，即不存在任何一門 John 的課是該生沒修或沒被當的。\n四、（四）姓名、總學分與平均分數\nSELECT S.Sname, SUM(C.CreditHour) AS 總學分, AVG(TC.Score) AS 平均分數\nFROM STUDENT S LEFT JOIN TAKE_COURSE TC ON S.S# = TC.S#\nLEFT JOIN COURSE C ON TC.C# = C.C#\nGROUP BY S.S#, S.Sname;\n說明：LEFT JOIN 讓沒修課的學生也列出；若總學分只計及格課程，可改用 SUM(CASE WHEN TC.Score >= 60 THEN C.CreditHour ELSE 0 END)。\n\n【關鍵字】\nJOIN、LEFT JOIN、GROUP BY、HAVING、COUNT DISTINCT、EXISTS、NOT EXISTS、相關子查詢、關聯除法、SUM、AVG、CASE WHEN\n\n【作答提醒】\n1. 第三小題的除法是最常失分處，要寫出雙重否定並用文字解釋。\n2. GROUP BY 要加上主鍵（S#），避免同名學生被合併。\n3. 題意有歧義處（一門課多位老師、學分是否只算及格）先寫明假設。"},{"n":3,"q":"一家醫院欲設計電子病歷系統，但對應窗口並無相關資訊技術，僅開出如下規格：[醫生資料]: 姓名, 科別, 年資, [門診資料]: 診別, 時間, 主治醫生, [病患]: 姓名, 個人資料, 另外也須紀錄[就診記錄]。\n（一）請根據想像設計一更完整的簡易醫院就診記錄查詢系統關聯資料庫，需能夠回答（二）的查詢，並繪出相關 ER diagram。（10 分）\n（二）請根據你設計的資料庫寫出下列相對應的 SQL 查詢字串：（10 分）在日期 D 來看內科且有拿藥的六十歲女性。同一科看過兩次的病患姓名與對應醫生年資。","pt":20,"warn":["pua"]},{"n":4,"q":"如果 scheme R = (A, B, C, D, E)，並滿足以下所有的 functional dependencies A→BC, CD→E, B→D, E→A\n（一）假設我們分解（decomposition）R 成為(A, B, C), (A, D, E)。證明這是一個 lossless-join分解。（10 分）\n（二）寫出一個 lossless-join 分解使得 R 分解後滿足 BCNF。（10 分）\n（三）寫出一個 lossless-join 分解使得 R 分解後滿足 3NF。（10 分）","pt":30},{"n":5,"q":"請解釋叢集索引與非叢集索引的意義與差別。（10 分）","pt":10}]},{"roc":105,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=105180&c=340&s=2201&q=1","qs":[{"n":1,"q":"美美藥妝店委託軟體公司建置管理資訊系統，資料庫的資料需求如下：z 顧客：一個顧客有一個顧客編號、顧客姓名、顧客住址、手機號碼。每個顧客編號是唯一的，一個顧客每次可購買數件藥妝商品。z 藥妝商品：每一件藥妝商品有一個藥妝商品編號、藥妝名稱、藥妝種類、單價、廠商編號。一件藥妝商品的藥妝商品編號是唯一的。z 供應商：每一個廠商有一個廠商編號、廠商名稱、廠商住址、廠商電話。每一個供應商的廠商編號是唯一的，每一個廠商每次可供應數件藥妝商品。z 訂單：每一筆訂單有一個訂單編號、訂單日期、數量、備註、顧客編號、藥妝商品編號。每一筆訂單的訂單編號是唯一的。\n（一）請繪製資料表關聯圖以呈現資料的概念模式。          （15 分）\n（二）若採用關聯式資料庫建置，請列出每個關聯資料表的綱要（Table Schema）           ，包括：表格名稱、屬性（Attribute）、主鍵（Primary Key）與外來鍵（Foreign Key）。（10 分）","pt":25},{"n":2,"q":"巨人電腦補習班有個關聯式資料庫（Relational Database），兩個資料表為授課 A、授課 B，資料表綱要如下所示：授課 A（教師編號、教師姓名、授課時間、授課教室）         ，功能相依性的假設為：每位教師姓名都不一樣，教師授課皆在教室內，教師在任何一個上課時段內只在一間教室上課。授課 B（教師編號、授課時間、授課教室、課程）      ，功能相依性的假設為：每位教師可授多門課程，但一門課程只由一位教師教授，教師授課皆在教室內，教師在任何一個上課時段內只在一間教室上課。若想要將各資料表分解成符合 BCNF（Boyce-Codd Normal Form）的資料表，請列出每個資料表的綱要與候選鍵（Candidate Key）。（20 分）全一張（背面）等   別：三等考試","pt":20,"warn":["fig"]},{"n":3,"q":"3Q 出版社販售中英文教科書，系統的關聯式資料庫（Relational Database）包含：書籍、客戶、訂單三個資料表（Table）  。書籍資料表記錄書籍編號、書籍名稱、書籍單價；客戶資料表記錄客戶編號、客戶姓名、客戶地址、客戶電話；訂單資料表記錄訂單編號、訂單日期、是否付款、書籍編號、數量、客戶編號，每筆訂單只有一位下訂單的客戶。這三個資料表的關聯綱要（Relational Schema）如下所示：書籍（書籍編號、書籍名稱、書籍單價）客戶（客戶編號、客戶姓名、客戶地址、客戶電話）訂單（訂單編號、訂單日期、是否付款、書籍編號、數量、客戶編號）有底線的屬性（Attribute）為該資料表的主鍵（Primary Key），針對下列三個查詢問題，請分別寫出 SQL 指令來進行查詢。（每小題 10 分，共 30 分）\n（一）請列出未付款且書籍訂購數量>=50 的客戶姓名與客戶電話。\n（二）請列出每本書籍的購買數量並按書籍編號由小到大排序。\n（三）請使用 NOT IN 語法列出沒有購買書籍編號為 A0009 的客戶編號、客戶姓名與客戶地址。","pt":30,"warn":["fig"]},{"n":4,"q":"網路興起帶動巨量資料現象，經過資料的整理、篩選及分析，可以幫助企業經營做決策，關聯式資料庫在資料結構設計上十分費工，造成傳統關聯式查詢相對緩慢，NoSQL 資料庫因應而生。\n（一）請說明關聯式資料庫與 NoSQL 資料庫的差異。（10 分）\n（二）若員工資料有：員工編號、姓名、身分證字號、年齡、部門、職稱、薪資，請列出關聯式資料庫資料表與 NoSQL 資料庫資料表。（15 分）","pt":25}]},{"roc":104,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=104180&c=343&s=2204&q=1","qs":[{"n":1,"q":"下列為包含五筆交易之交易資料庫，在購買的商品欄位中，每一個英文字母代表一種商品，例如編號 T100 的交易購買 M、O、N、K、E、Y 六種商品。交易編號           購買的商品T100       {M, O, N, K, E, Y} T200       {D, O, N, K, E, Y} T300       {M, A, K, E} T400       {M, U, C, K, Y} T500       {C, O, K, I, E}關聯規則的形式為 A⇒B，其中 A 與 B 皆為商品的集合（例如{M, K}），表示如果顧客買了 A 集合的商品就會買 B 集合的商品。假設最小支持度與最小信賴度分別為 60%與 80%，請找出所有滿足最小支持度與最小信賴度的關聯規則。（20 分）","pt":20,"warn":["fig"]},{"n":2,"q":"檜木傢俱公司製造與販售傢俱，其關聯式資料庫（Relational Database）包含了顧客、訂單、傢俱及訂購四個表格（Table） 。顧客表格記錄顧客編號、顧客名稱和顧客地址；訂單表格記錄訂單編號、訂單日期和下訂單的顧客編號，每一個訂單只有一位下訂單的顧客；傢俱表格記錄傢俱編號、傢俱名稱和傢俱定價；訂購表格記錄某一個訂單訂購某一種傢俱以及訂購傢俱的數量。這四個表格的關聯綱要（Relational Schema）如下所示：顧客（顧客編號、顧客名稱、顧客地址）訂單（訂單編號、訂單日期、顧客編號）傢俱（傢俱編號、傢俱名稱、傢俱定價）訂購（訂單編號、傢俱編號、訂購數量）有底線的屬性（Attribute）為該表格之主鍵（Primary Key）；例如，訂購表格之主鍵為訂單編號與傢俱編號兩個屬性的組合。訂單表格有一個外來鍵（Foreign Key）顧客編號，參照顧客表格的主鍵。訂購表格有訂單編號與傢俱編號兩個外來鍵，分別參照訂單表格與傢俱表格的主鍵。針對下列三個查詢問題，請各寫出一個 SQL 指令來進行查詢。\n（一）列出售價（定價打八折）小於 10000 的每一種傢俱之傢俱編號與傢俱名稱。      （10 分）\n（二）列出訂購各種傢俱的總數量大於 12 的每一個訂單之訂單編號及其訂購各種傢俱的總數量。（15 分）\n（三）列出所有訂單都有訂購的傢俱之傢俱編號與傢俱名稱。（15 分）全一張（背面）等    別：三等考試","pt":40,"warn":["fig"]},{"n":3,"q":"「資料獨立」（Data Independence）是使用資料庫的方法來管理資料的優點之一，請說明資料獨立的做法及資料獨立的優點。        （20 分）","pt":20},{"n":4,"q":"供應商供應（供應商編號，供應商城市，供應商等級，零件編號，零件供應數量）是一個關聯綱要，其中供應商供應為表格名稱，供應商編號、供應商城市、供應商等級、零件編號和零件供應數量為表格的五個屬性，供應商編號與零件編號兩個屬性的組合為表格的主鍵，同時也是該表格唯一的候選鍵（Candidate Key）        。另外，供應商供應表格有下列四個功能相依（Functional Dependency）：（每小題 10 分，共 20 分）{供應商編號，零件編號} → {零件供應數量} {供應商編號} → {供應商城市} {供應商編號} → {供應商等級} {供應商城市} → {供應商等級}\n（一）請問供應商供應表格符合第幾正規型式（Normal Form）？請說明理由。\n（二）供應商供應表格應該要正規化到第幾正規型式才適當？請將供應商供應表格正規化到適當的正規型式，寫出正規化之後每一個表格的綱要，包括表格名稱、屬性、主鍵及外來鍵（如果有外來鍵的話）   。","pt":20}]},{"roc":103,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=103180&c=344&s=2204&q=1","qs":[{"n":1,"q":"將下列 EERD 轉成滿足第三正規化（The 3rd normal form）的 Table，每個 Table 均必須標明其擁有之 PK、FK（否則該 Table 不給分），圖中（…）代表 Composite attribute；{…}代表 Multivalued attribute；雙底線者為 Partial identifier；雙線菱形為Identifying relationship。（25 分）[註] D→E、D+F→G ABC                        D E {F G(G1 G2)} d PQRS HJ                KM TUV WXY","pt":25},{"n":2,"q":"請將下列二表單之資料，以 ERD（Entity Relationship Diagram）表示之，但請遵守下列原則： 每個 Entity 均必須滿足第三正規化（The 3rd normal form）、 所有Entity 均要標示其 Identifier(PK)、 每個 Relationship 都要有 Cardinality。（25 分）員工資料員工代碼    姓名      性別    電話    任職部門代碼       部門名稱           直屬主管    配偶M001   David    M    111      HO      Head Office R002    Sam     M    222      RD          R&D          M001    F005 R003    Amy     F    333      RD          R&D          R002 F004   Katy     F    444      FN       Financial       F006 F005   Mary     F    555      FN       Financial       F006    R002 F006   Steve    M    666      FN       Financial       M001 R007   Jason    M    777      FN       Financial       F006主管資料員工代碼     姓名     性別        職稱代號    職稱M001   David    M         M1    Manager R002    Sam     M         C1     Chief F006   Steve    M         C1     Chief全一張（背面）等   別： 三等考試","pt":25,"warn":["math"]},{"n":3,"q":"有一個 ERD 如下圖，學校採用申請入學，首先接受入學申請，而後統一甄選，公布錄取名單，所以，舉凡學生都有一份入學申請，被接受就成為學生；反之，則不是。入學申請資料與學生資料都要留存於電腦系統中。學號                                     申請書號姓名    學生                       入學申請    送件日性別生日如果實體設計時，將一對一關係轉化成一個 Relation，設計結果如下，請問有何缺點？（10 分）學生(學號 姓名 性別 生日 申請書號 送件日)考量另一種設計方案，如果入學申請做成一個 Table；而學生 Entity 實作如下：Create table 學生(學號 nchar(10) primary key,姓名 char(12),性別 char(2),生日 datetime,申請書號 nchar(10) not null references 入學申請(申請書號) on delete cascade)請問：    「申請書號」為何要宣告「not null」？（5 分）依前述「申請書號」的設定，刪除一筆學生資料，其對應的入學申請資料會如何？（10 分）","pt":25,"warn":["fig","math"]},{"n":4,"q":"四個異動對同一標的物做操作，其動作序列如下 表，請分別以 ： X-Locking（X 鎖-鎖定法）、 Versioning（版本法）與 Timestamping（時間戳記法）模擬之（要有過程之說明；否則，不給分），並說出最後分別有那些異動被執行？（25 分）T1      T2      T3       T4 1     Read 2      ●              Read 3      ●      Read     ● 4      ●       ●       ● 5      ●      Write    ● 6     Write            ● 7                      ●       Read 8                     Write     ● 9                              Write","pt":25,"warn":["math"]}]},{"roc":102,"mins":120,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=102190&c=341&s=2204&q=1","qs":[{"n":1,"q":"資料倉儲（Data Warehouse）是一種決策支援資料庫，採用維度模式（Dimension Model）作為使用者分析資料的資料模式。在維度模式的架構中，所有的表格被歸類為那兩種類型的表格？請說明這兩種表格的結構以及所包含的資料。（20 分）","pt":20},{"n":2,"q":"某一所大學的關聯式資料庫（Relational Database）包含了學生、課程及修課三個表格（Table），學生表格與課程表格分別記錄學生與課程的基本資料，修課表格則記錄學生修完那些課程及其成績。這三個表格的關聯綱要（Relational Schema）如下所示：學生（學號，學生姓名，性別，地址，主修科系）課程（課程編號，課程名稱，開課科系）修課（學號，課程編號，成績）有底線的屬性（Attribute）為該表格之主鍵（Primary Key）；例如，修課表格之主鍵為學號與課程編號兩個屬性的組合。修課表格有學號與課程編號兩個外來鍵（Foreign Key），分別參照學生表格與課程表格的主鍵。修課表格中成績屬性的值為介於 0 到 100 之間的整數。針對下列三個查詢問題，請各寫出一個 SQL 指令來進行查詢。\n（一）列出開課科系為 '資訊管理學系' 的每一門課程之課程編號與課程名稱。（10 分）\n（二）列出平均成績大於 75 的每一位學生之學號及其平均成績。（10 分）\n（三）列出修完所有課程的每一位學生之學號與學生姓名。（10 分）","pt":30,"warn":["fig"]},{"n":3,"q":"R (A, B, C, D, E)是一個關聯綱要，其中 R 為關聯名稱，A、B、C、D、E 為 R 的五個屬性，{A, B}兩個屬性的組合為 R 的主鍵。假設 R 符合第一正規型式（First Normal Form, 1NF），另外，R 有下列四個功能相依（Functional Dependency）：{A, B} → {C} {B} → {D} {B} → {E} {D} → {E}\n（一）何謂關聯式資料庫正規化（Normalization）？其目的為何？（10 分）\n（二）何謂第二正規型式（Second Normal Form, 2NF）？R 是否符合第二正規型式？請說明理由。（10 分）\n（三） R 應該要正規化到第幾正規型式才適當呢？請將 R 正規化到適當的正規型式。（10 分）","pt":30},{"n":4,"q":"父型態/子型態關係（Supertype/Subtype Relationship）為擴充實體關係模式（Enhanced Entity-Relationship Model）中的重要觀念，而特殊化（Specialization）與一般化（Generalization）為產生父型態/子型態關係的兩種方式：\n（一）請定義「特殊化」。（10 分）\n（二）請定義「一般化」。（10 分）","pt":20}]}];
